window.PROJECT_H_SCENES["com_11"]=[
{"rowNumber":9,"id":"com_11.ks#9","kind":"text","speaker":"나레이션","english":"","japanese":"そんなこんなで、朝食後にぼくは水蓮姉さんから頼まれた手伝いに従事した。\n家の拭き掃除やハタキかけ、お客さんのいないコテージの清掃手伝いだ。","korean":"아침을 먹고 나서는 스이렌 누나가 부탁한 일을 도왔다.\n집 안을 걸레로 닦고 먼지를 턴 다음, 손님이 없는 숙소도 함께 청소했다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":13,"id":"com_11.ks#13","kind":"text","speaker":"나레이션","english":"","japanese":"掃除ぐらいと思っていたが、しっかりやろうとすると中々運動になったし、\n終わってみれば、綺麗になっていくのを見るのが気持ちの良いものだった。","korean":"청소쯤이야 했는데 제대로 하려니 제법 운동이 된다.\n그래도 다 끝내고 말끔해진 곳을 보니 기분이 좋았다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":28,"id":"com_11.ks#28","kind":"text","speaker":"名前","english":"","japanese":"「ふう……」","korean":"「후우……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":33,"id":"com_11.ks#33","kind":"text","speaker":"나레이션","english":"","japanese":"掃除が終わり、今ぼくは一人で外に出ていた。\n照りつける日差しで暑いが、吹き付ける風は心地いい。","korean":"청소를 끝내고 지금은 혼자 밖에 나와 있다.\n햇볕은 뜨겁지만 불어오는 바람은 기분 좋다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":37,"id":"com_11.ks#37","kind":"text","speaker":"나레이션","english":"","japanese":"セミの声はうるさいくらいだけど、これも夏らしい風情が感じられる。","korean":"매미 소리는 귀가 따가울 정도다. 그래도 이 소리를 들으니 여름이 온 게 실감 난다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":40,"id":"com_11.ks#40","kind":"text","speaker":"나레이션","english":"","japanese":"水蓮姉さんはコテージの事務仕事のため部屋にこもり、\n紫苑は委員会の仕事で学園に顔を出してくるとかで、登校していった。","korean":"스이렌 누나는 숙소 업무를 처리하러 방에 들어갔고,\n시온은 위원회 일로 학교에 잠깐 다녀온다며 나갔다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":45,"id":"com_11.ks#45","kind":"text","speaker":"名前","english":"","japanese":"「さてと……」","korean":"「그럼 어디……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":48,"id":"com_11.ks#48","kind":"text","speaker":"나레이션","english":"","japanese":"そうして一人になったぼくは、この機会に家付近の地理だけでも\nしっかり把握しておくべく、散歩に出たところだ。","korean":"혼자가 된 김에 적어도 집 주변 길은 제대로 익혀 두려고 산책에 나왔다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":52,"id":"com_11.ks#52","kind":"text","speaker":"나레이션","english":"","japanese":"……じゃないとまたこの前みたいに、山に迷い込んでしまいそうだから。\n巨大熊には会いたくないし。","korean":"……안 그러면 저번처럼 또 산속에서 헤맬 것 같다.\n그 거대한 곰도 만나기 싫고.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":57,"id":"com_11.ks#57","kind":"text","speaker":"名前","english":"","japanese":"「じゃ、行ってきまーす」","korean":"「그럼 다녀올게!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":62,"id":"com_11.ks#62","kind":"text","speaker":"水蓮","english":"","japanese":"「気をつけてね。お昼ご飯までには帰ってねー」","korean":"「조심해서 다녀와. 점심 먹기 전엔 돌아오고!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":66,"id":"com_11.ks#66","kind":"text","speaker":"名前","english":"","japanese":"「うん、それじゃあ、行ってくるよ」","korean":"「응, 이따 봐.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":69,"id":"com_11.ks#69","kind":"text","speaker":"나레이션","english":"","japanese":"玄関に向かって声をかけると、奥の方から\n優しい送り出しの声が返ってきた。","korean":"현관에서 집 안쪽을 향해 소리치자, 누나의 다정한 목소리가 들려왔다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":73,"id":"com_11.ks#73","kind":"text","speaker":"나레이션","english":"","japanese":"こんな風に送り出されるなんて、なんだか子供の頃に戻ったみたいだ。\n思わず、笑みがこぼれる。","korean":"이렇게 배웅받으니 어릴 때로 돌아간 것 같다.\n나도 모르게 웃음이 난다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":77,"id":"com_11.ks#77","kind":"text","speaker":"나레이션","english":"","japanese":"子供の頃の夏休みにはこうして、自宅でもこの島でも、\nぼくは『遊びに行ってきまーす』なんて飛び出して、\n水蓮姉さんや母さんに送り出されてたっけ……。","korean":"어릴 때 여름방학이면 집에서든 이 섬에서든 ‘놀다 올게!’ 하고 뛰어나갔지.\n스이렌 누나랑 엄마가 이렇게 배웅해 주곤 했는데……","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":92,"id":"com_11.ks#92","kind":"text","speaker":"名前","english":"","japanese":"「そうだ、母さん……」","korean":"「아, 맞다. 엄마……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":95,"id":"com_11.ks#95","kind":"text","speaker":"나레이션","english":"","japanese":"母さん、で思い出した。実家の方にも電話しておかないと。","korean":"엄마 생각이 나고서야 떠올랐다. 집에도 전화해 둬야지.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":98,"id":"com_11.ks#98","kind":"text","speaker":"나레이션","english":"","japanese":"ぼくは、木陰に入ってポケットからスマホを取り出した。","korean":"나무 그늘에 들어가 주머니에서 휴대폰을 꺼냈다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":109,"id":"com_11.ks#109","kind":"text","speaker":"名前","english":"","japanese":"「あ、もしもし？　ぼくだけど……\nうん、今、水蓮姉さんたちの家で……」","korean":"「어, 여보세요? 엄마, 나야……\n응, 지금 스이렌 누나네 집에 있어.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":114,"id":"com_11.ks#114","kind":"text","speaker":"名前","english":"","japanese":"「水蓮姉さんにも紫苑にも会えたよ。\nやっぱり、前に民宿だった家をそのまま自宅にして、\n近くにコテージを持ってて……そう、そう……」","korean":"「스이렌 누나랑 시온이 둘 다 만났어.\n전에 민박하던 집은 지금 그냥 살림집으로 쓰고, 근처에 따로 숙소가 있더라.\n응, 맞아……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":119,"id":"com_11.ks#119","kind":"text","speaker":"나레이션","english":"","japanese":"電話をかけると、母さんが出た。\nここに来ることはもちろん伝えてあるから、その後のことを簡単に報告していく。","korean":"전화를 걸자 엄마가 받았다.\n섬에 온다는 얘긴 이미 해 뒀으니, 도착해서 어떻게 지내는지만 간단히 알려 드린다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":124,"id":"com_11.ks#124","kind":"text","speaker":"名前","english":"","japanese":"「そうだね、せっかくの夏休みだし、しばらくこっちで\n水蓮姉さんたちの手伝いなんかをさせてもらおうと思って……」","korean":"「그러게. 모처럼 여름방학이니까 당분간 여기서\n스이렌 누나랑 시온이 하는 일도 좀 돕고 그러려고.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":129,"id":"com_11.ks#129","kind":"text","speaker":"名前","english":"","japanese":"「学年が上がると、夏休みでも大学に行くことが増えるからさ。\nゆっくり休めるのは今年くらいだって言われたしね」","korean":"「학년 올라가면 여름방학에도 학교에 나갈 일이 많아진대.\n이렇게 푹 쉴 수 있는 건 올해가 거의 마지막이라더라.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":133,"id":"com_11.ks#133","kind":"text","speaker":"나레이션","english":"","japanese":"ぼくの言葉を聞きながら、母さんは相槌を打ったり\nあれこれ尋ねてきたり。","korean":"엄마는 내 말을 들으며 맞장구도 치고 이것저것 물어보셨다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":137,"id":"com_11.ks#137","kind":"text","speaker":"나레이션","english":"","japanese":"ついでに、隣に父さんもいるようで、時折母さんが父さんにぼくの言葉を伝えて、\n父さんが相槌を打っているのも聞こえてくる。","korean":"아빠도 옆에 계신가 보다. 엄마가 중간중간 내 말을 옮기면,\n아빠가 맞장구치는 소리도 들린다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":141,"id":"com_11.ks#141","kind":"text","speaker":"나레이션","english":"","japanese":"そして母さんは、夏休みに入る前からぼくに言っていた\n台詞を言い始めた。","korean":"그러더니 엄마는 방학 전부터 하던 말을 또 꺼냈다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":145,"id":"com_11.ks#145","kind":"text","speaker":"나레이션","english":"","japanese":"これまでは受験勉強、大学に入れてからも勉強勉強で根を詰めすぎてたように\n見えるから、この機会にしっかりリフレッシュしなさいよ！　と。","korean":"입시 때도, 대학에 들어가서도 공부만 하느라 너무 무리하는 것 같으니\n이번 기회에 제대로 쉬고 오라는 얘기였다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":149,"id":"com_11.ks#149","kind":"text","speaker":"나레이션","english":"","japanese":"両親から見るとぼくは、親が勉強しろと言わないのに勝手に勉強して、\n勝手に根を詰めすぎる珍しい子供なんだとか。","korean":"엄마 아빠 눈에는 공부하란 소리도 안 했는데 혼자 공부하다 혼자 무리하는,\n참 별난 자식인 모양이다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":154,"id":"com_11.ks#154","kind":"text","speaker":"名前","english":"","japanese":"「わかったよ。しっかりリフレッシュするって。\nうん、母さんも身体に気をつけて、父さんにも\nよろしく伝えておいて。じゃあ……」","korean":"「알았어. 제대로 쉬다 갈게.\n응, 엄마도 몸조심하고, 아빠한테도 안부 전해 줘. 그럼 끊을게……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":162,"id":"com_11.ks#162","kind":"text","speaker":"名前","english":"","japanese":"「色々心配かけちゃってたってことだよなぁ……」","korean":"「내가 그동안 걱정을 많이 끼쳤나 보네……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":165,"id":"com_11.ks#165","kind":"text","speaker":"나레이션","english":"","japanese":"電話を切った後で、ぼくは苦笑する。","korean":"전화를 끊고 씁쓸하게 웃었다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":168,"id":"com_11.ks#168","kind":"text","speaker":"나레이션","english":"","japanese":"父さん母さんは、いつもぼくにもっと遊んでこいって言うんだ。\n勉強もいいけど根を詰めすぎるな、なんて。","korean":"엄마 아빠는 늘 나한테 나가서 좀 더 놀다 오라고 하신다.\n공부도 좋지만 너무 무리하지는 말라고.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":172,"id":"com_11.ks#172","kind":"text","speaker":"나레이션","english":"","japanese":"普通の家だと、逆だと思うけど……。\n両親の言うように、ぼくがちょっと変なんだろうか。","korean":"보통 집이랑은 반대인 것 같은데……\n두 분 말대로 내가 좀 별난 건가.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":180,"id":"com_11.ks#180","kind":"text","speaker":"名前","english":"","japanese":"「ふう、いい風だな……」","korean":"「후우, 바람 좋다……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":183,"id":"com_11.ks#183","kind":"text","speaker":"나레이션","english":"","japanese":"心地いい風に頬を撫ぜられながら、ぼくは空を見上げる。","korean":"기분 좋은 바람이 뺨을 스친다. 나는 고개를 들어 하늘을 본다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":194,"id":"com_11.ks#194","kind":"text","speaker":"나레이션","english":"","japanese":"澄み渡る青くて高い空、まぶしくて大きな太陽。\n都会の空より、青が濃くて深い気がする。","korean":"높고 맑은 파란 하늘에 커다란 해가 눈부시다.\n도시에서 보던 하늘보다 파란빛이 더 짙고 깊은 것 같다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":198,"id":"com_11.ks#198","kind":"text","speaker":"나레이션","english":"","japanese":"向こうの方には、きらきら光る海も見える。\n都会の方じゃ、とてもじゃないけどお目にかかれない美しい景色だ。","korean":"저 멀리 반짝이는 바다도 보인다.\n도시에서는 좀처럼 마주할 수 없는 아름다운 풍경이다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":202,"id":"com_11.ks#202","kind":"text","speaker":"나레이션","english":"","japanese":"……そうだ、まずは海岸沿いの道を把握しておくとしよう。","korean":"……그래, 우선 바닷가를 따라가는 길부터 익혀 두자.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":205,"id":"com_11.ks#205","kind":"text","speaker":"나레이션","english":"","japanese":"海岸沿いに行けば、港の方にも確実に出られるわけだし、\n少なくとも先日のようにあてどなくさ迷うような事態は避けられるはずだ。","korean":"해안길만 따라가면 항구에도 틀림없이 닿을 테니,\n적어도 지난번처럼 갈 곳을 몰라 헤맬 일은 없겠지.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":222,"id":"com_11.ks#222","kind":"text","speaker":"名前","english":"","japanese":"（セミも相変わらず多いなぁ……）","korean":"(매미는 여전히 많네……)","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":225,"id":"com_11.ks#225","kind":"text","speaker":"나레이션","english":"","japanese":"太陽のまぶしさに目を細め、海岸沿いをゆっくりと\n歩きながら、ぼくは物思いに耽っていた。","korean":"눈부신 햇볕에 눈을 가늘게 뜨고 바닷가를 천천히 걸으며 생각에 잠겼다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":229,"id":"com_11.ks#229","kind":"text","speaker":"나레이션","english":"","japanese":"島に来たのはリフレッシュ目的だけど、せっかくの機会だから、\nゆっくりと考えてみたいことがあった。","korean":"쉬러 온 섬이지만, 모처럼 시간이 난 김에 천천히 생각해 보고 싶은 게 있었다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":233,"id":"com_11.ks#233","kind":"text","speaker":"나레이션","english":"","japanese":"自分の将来について……\nというと大げさというか自分探しみたいで恥ずかしいけど。","korean":"내 앞날에 대해서다……\n이렇게 말하니 무슨 자아 찾기라도 하러 온 것 같아 좀 쑥스럽지만.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":237,"id":"com_11.ks#237","kind":"text","speaker":"나레이션","english":"","japanese":"医者になりたいと思って頑張っては来た……だけどそもそも、\nぼくは何で医者になりたかったのか、わからなくなってきている。","korean":"의사가 되고 싶어서 열심히 달려왔다. 그런데 정작 내가 왜 의사가 되고 싶었는지는 점점 모르겠다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":241,"id":"com_11.ks#241","kind":"text","speaker":"나레이션","english":"","japanese":"医学部入るために勉強するのは目の前のことに集中するだけだったから、\n悩むようなこともなかったんだけど。","korean":"의대에 들어가려고 공부할 때는 눈앞의 일만 보면 됐으니,\n이런 고민을 할 일도 없었는데.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":246,"id":"com_11.ks#246","kind":"text","speaker":"名前","english":"","japanese":"（燃え尽き症候群、ってやつかな……？）","korean":"(이게 번아웃이라는 건가……?)","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":249,"id":"com_11.ks#249","kind":"text","speaker":"나레이션","english":"","japanese":"これまで勉強勉強と張り詰めていたものが\n緩んでしまったというだけかもしれない。","korean":"그동안 공부만 하느라 바짝 긴장했던 게 이제 좀 풀린 것뿐인지도 모른다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":253,"id":"com_11.ks#253","kind":"text","speaker":"나레이션","english":"","japanese":"穏やかに流れるこの島の時間の中で、自分を見つめなおしてみよう。\n案外、あっさりと動機というか切欠を思い出すかもしれないし。","korean":"시간이 느리게 흐르는 이 섬에서 내가 뭘 원하는지 다시 생각해 보자.\n의사가 되고 싶었던 계기도 의외로 쉽게 떠오를지 모르고.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":258,"id":"com_11.ks#258","kind":"text","speaker":"名前","english":"","japanese":"「…………」","korean":"「…………」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":265,"id":"com_11.ks#265","kind":"text","speaker":"나레이션","english":"","japanese":"そんなことをつらつらと考えていたが、こうしてこの島で海や空を眺めていると、\n心が洗われるというか、気持ちがクリアになっていく気がする。","korean":"이런저런 생각을 하다가도 이렇게 바다와 하늘을 바라보고 있으면,\n마음이 씻기는 것처럼 머릿속이 맑아진다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":269,"id":"com_11.ks#269","kind":"text","speaker":"나레이션","english":"","japanese":"そして、昨日の夜、夢うつつで思い出していた昔の彼女たちの姿が脳裏に蘇る。","korean":"그러다 어젯밤 잠결에 떠올렸던 두 사람의 옛 모습이 다시 눈앞에 그려진다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":273,"id":"com_11.ks#273","kind":"text","speaker":"名前","english":"","japanese":"「…………」","korean":"「…………」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":276,"id":"com_11.ks#276","kind":"text","speaker":"나레이션","english":"","japanese":"成長した二人に残る子供の頃の面影に懐かしさを感じ、\n自然と口元に笑みが浮かぶ。","korean":"다 큰 두 사람에게서 어릴 적 모습이 겹쳐 보인다. 새삼 그리운 마음에 저절로 웃음이 난다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":280,"id":"com_11.ks#280","kind":"text","speaker":"나레이션","english":"","japanese":"この島で二人と過ごしてたら、ぼくの小さな悩みなんて消えてしまうかも。","korean":"이 섬에서 둘과 지내다 보면 이런 작은 고민쯤은 사라질지도 모른다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":283,"id":"com_11.ks#283","kind":"text","speaker":"나레이션","english":"","japanese":"しかし、昨日はまいったな……あんな状況になるなんて。\n他人が見たら羨ましがられるかもしれないけど、当事者として困りモノだ。","korean":"그래도 어제는 정말 난감했다. 그런 상황이 될 줄이야……\n남들이 보면 부러워할지 몰라도, 막상 겪은 나는 곤란하기만 했다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":287,"id":"com_11.ks#287","kind":"text","speaker":"나레이션","english":"","japanese":"綺麗な水蓮姉さんの寝顔も、紫苑の可愛い寝顔も……胸元なんかも見えちゃうし、\nなんか良い匂いもするしで、ちょっと刺激的すぎて──","korean":"스이렌 누나의 아름다운 잠든 얼굴과 시온의 귀여운 잠든 얼굴. 가슴께도 보이고,\n좋은 향까지 나니 자극이 너무 강해서……","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":297,"id":"com_11.ks#297","kind":"text","speaker":"名前","english":"","japanese":"「う……」","korean":"「으……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":300,"id":"com_11.ks#300","kind":"text","speaker":"나레이션","english":"","japanese":"ここで、一気に不謹慎な気分になってきた。","korean":"순식간에 딴생각이 머릿속을 채운다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":303,"id":"com_11.ks#303","kind":"text","speaker":"나레이션","english":"","japanese":"直前まで割と真面目なことを考えていたのに消し飛んだ。\nそう考えると、案外悩みなんてその程度なのかもしれないけど。","korean":"방금 전까지만 해도 꽤 진지한 고민 중이었는데 싹 날아갔다.\n어쩌면 내 고민이라는 게 생각보다 별것 아닐지도 모르지만.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":307,"id":"com_11.ks#307","kind":"text","speaker":"나레이션","english":"","japanese":"まあ、旅の準備やらでバタバタして、その後は長旅だったから、\n実はしばらくオナニーもしてないせいもあると思う。","korean":"여행 준비로 정신없다가 먼 길을 오느라 실은 한동안 혼자 풀지도 못했다. 그것도 한몫했겠지.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":311,"id":"com_11.ks#311","kind":"text","speaker":"나레이션","english":"","japanese":"そんな溜まってる状態で水蓮姉さんや紫苑の無防備な姿を見ちゃったり、\n水蓮姉さんからスキンシップされるもんだから、心が揺れてしまう。","korean":"그런 상태에서 스이렌 누나랑 시온이 저렇게 무방비한 모습을 보이고,\n스이렌 누나가 자꾸 다정하게 안아 주니 마음이 흔들린다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":315,"id":"com_11.ks#315","kind":"text","speaker":"나레이션","english":"","japanese":"というか、海綿体に血液が流れ込み膨張してしまう。","korean":"아니, 마음만 흔들린다는 말로는 부족하다. 해면체에 피가 몰려 부풀고 있다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":319,"id":"com_11.ks#319","kind":"text","speaker":"名前","english":"","japanese":"「……っ……」","korean":"「……읏……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":322,"id":"com_11.ks#322","kind":"text","speaker":"나레이션","english":"","japanese":"頭を振って雑念を必死で散らそうと試みつつ、足を進めるのだった。","korean":"고개를 흔들어 잡생각을 어떻게든 떨쳐 내며 계속 걸었다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":337,"id":"com_11.ks#337","kind":"text","speaker":"나레이션","english":"","japanese":"そんなこんなで辺りをぐるりと歩き回っているうちにちょうどいい時間となり、\nぼくは悶々としつつも平静を装って、若弥家に戻ることにした。","korean":"그렇게 주변을 한 바퀴 돌고 나니 마침 돌아갈 시간이다.\n속은 여전히 싱숭생숭하지만, 아무렇지 않은 척 와카미네 집으로 돌아가기로 했다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":356,"id":"com_11.ks#356","kind":"text","speaker":"名前","english":"","japanese":"「ただいまー」","korean":"「나 왔어!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":364,"id":"com_11.ks#364","kind":"text","speaker":"水蓮","english":"","japanese":"「おかえり。お昼ご飯できてるよ」","korean":"「어서 와. 점심 다 됐어.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":372,"id":"com_11.ks#372","kind":"text","speaker":"紫苑","english":"","japanese":"「……おかえり」","korean":"「……어서 와.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":377,"id":"com_11.ks#377","kind":"text","speaker":"名前","english":"","japanese":"「あ、ただいま、紫苑……紫苑もおかえり、かな？」","korean":"「아, 응. 시온아…… 너한테도 어서 오라고 해야 하나?」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":382,"id":"com_11.ks#382","kind":"text","speaker":"紫苑","english":"","japanese":"「そうよ」","korean":"「그렇지.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":386,"id":"com_11.ks#386","kind":"text","speaker":"나레이션","english":"","japanese":"玄関を開けると水蓮姉さんが出迎えてくれて、紫苑もいた。","korean":"현관문을 열자 스이렌 누나가 맞아 주었다. 시온도 함께 있었다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":389,"id":"com_11.ks#389","kind":"text","speaker":"나레이션","english":"","japanese":"紫苑も、ちょうど学園から戻ってきたところらしい。","korean":"시온도 마침 학교에서 막 돌아온 모양이다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":395,"id":"com_11.ks#395","kind":"text","speaker":"水蓮","english":"","japanese":"「ほら、二人とも入って。居間に準備してるからね」","korean":"「둘 다 얼른 들어와. 거실에 점심 차려 뒀어.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":400,"id":"com_11.ks#400","kind":"text","speaker":"名前","english":"","japanese":"「うん、ありがとう、水蓮姉さん」","korean":"「응, 고마워, 스이렌 누나.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":407,"id":"com_11.ks#407","kind":"text","speaker":"紫苑","english":"","japanese":"「今日のお昼って、もしかして素麺じゃない？　ほら、こないだの……」","korean":"「오늘 점심 혹시 소면이야? 있잖아, 얼마 전에 받은 거……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":415,"id":"com_11.ks#415","kind":"text","speaker":"水蓮","english":"","japanese":"「そうだよ。いただきものがあったからね。\n二人とも、手を洗ってきてね、ふふ」","korean":"「맞아. 선물로 받은 게 있었잖아.\n둘 다 손 씻고 와. 후후.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":420,"id":"com_11.ks#420","kind":"text","speaker":"名前","english":"","japanese":"「わかったよ……なんかこういうやりとり、子供の頃を思い出すよね、紫苑」","korean":"「알았어…… 이렇게 얘기하니까 어릴 때 생각난다. 그치, 시온아?」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":425,"id":"com_11.ks#425","kind":"text","speaker":"紫苑","english":"","japanese":"「そうね……」","korean":"「그러네……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":430,"id":"com_11.ks#430","kind":"text","speaker":"名前","english":"","japanese":"「あ、はは……」","korean":"「아, 하하……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":433,"id":"com_11.ks#433","kind":"text","speaker":"나레이션","english":"","japanese":"うーん、中々難しいなぁ……まあでも、返事を返してくれるし、\n立ち去らずそばにいてくれてるだけでもありがたい……かな。","korean":"음, 아직은 어렵다…… 그래도 대답도 해 주고,\n휙 가 버리지 않고 곁에 있어 주는 것만 해도 고마워해야 하나.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":440,"id":"com_11.ks#440","kind":"text","speaker":"水蓮","english":"","japanese":"「はい、入って入って。まずは洗面所だよ」","korean":"「자, 얼른 들어와. 우선 손부터 씻고.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":444,"id":"com_11.ks#444","kind":"text","speaker":"나레이션","english":"","japanese":"ぼくたちは水蓮姉さんに促されて順番に洗面所で\n手を洗い、揃って居間へ向かうのだった。","korean":"스이렌 누나 말대로 세면실에서 차례로 손을 씻고 함께 거실로 간다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":460,"id":"com_11.ks#460","kind":"text","speaker":"水蓮","english":"","japanese":"「はい、どうぞ」","korean":"「자, 먹어.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":465,"id":"com_11.ks#465","kind":"text","speaker":"名前","english":"","japanese":"「豪華だね……素麺っていうから、もっとシンプルに想像してたけど……」","korean":"「푸짐하다…… 소면이라길래 더 간단할 줄 알았는데.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":472,"id":"com_11.ks#472","kind":"text","speaker":"水蓮","english":"","japanese":"「今日のメニューはいただきものの素麺と、\n夏野菜の天ぷら、山菜の素揚げだよ」","korean":"「오늘은 선물 받은 소면에 여름 채소 튀김이야.\n산나물은 튀김옷 없이 바로 튀겼고.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":478,"id":"com_11.ks#478","kind":"text","speaker":"名前","english":"","japanese":"「美味しそう……いただきます！」","korean":"「맛있겠다…… 잘 먹을게!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":481,"id":"com_11.ks#481","kind":"text","speaker":"나레이션","english":"","japanese":"しっとり光る素麺と、からっと揚がった天ぷら。","korean":"촉촉하게 윤이 나는 소면에 바삭하게 튀겨 낸 채소.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":484,"id":"com_11.ks#484","kind":"text","speaker":"나레이션","english":"","japanese":"天ぷらがお昼ご飯に出てくるとか、凄くないだろうか。\n既に口の中で唾液が分泌されているのがわかる。","korean":"점심부터 이런 튀김이라니, 대단하지 않나.\n보기만 해도 벌써 입에 침이 고인다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":494,"id":"com_11.ks#494","kind":"text","speaker":"紫苑","english":"","japanese":"「……いただきます。そうだ、お姉ちゃん、今日は新規のお客さんなし？」","korean":"「……잘 먹을게. 아, 언니. 오늘 새로 오는 손님 없어?」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":502,"id":"com_11.ks#502","kind":"text","speaker":"水蓮","english":"","japanese":"「うん、滞在してたお客様も朝お帰りになったし……。\nあ、そうだ、せっかくだから、皆で少しだけお出かけしない？」","korean":"「응, 묵던 손님들도 아침에 가셨고……\n아, 그러고 보니 다 같이 잠깐 어디 다녀올까?」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":508,"id":"com_11.ks#508","kind":"text","speaker":"名前","english":"","japanese":"「おでかけ？」","korean":"「어디 가게?」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":519,"id":"com_11.ks#519","kind":"text","speaker":"水蓮","english":"","japanese":"「せっかくこの島に戻ってきたんだから、海で遊ぼうよ。\nこの島と言えば海、でしょ？　ふふ」","korean":"「모처럼 섬에 돌아왔으니 바다에 가서 놀자.\n이 섬 하면 바다잖아. 후후.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":527,"id":"com_11.ks#527","kind":"text","speaker":"名前","english":"","japanese":"「あ……」","korean":"「아……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":530,"id":"com_11.ks#530","kind":"text","speaker":"나레이션","english":"","japanese":"海。\nつまり、展望台から見ていたあの浜辺だ。","korean":"바다라면, 전망대에서 내려다봤던 그 해변이다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":534,"id":"com_11.ks#534","kind":"text","speaker":"나레이션","english":"","japanese":"あそこは若弥家の土地で、ぼくたちにとっては\n子供の頃の思い出がたくさん詰まった場所でもある。","korean":"와카미네 땅이고, 우리 셋의 어릴 적 추억이 가득한 곳이기도 하다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":538,"id":"com_11.ks#538","kind":"text","speaker":"나레이션","english":"","japanese":"でもぼくは、実は泳ぎは苦手なんだよな……\nとはいえ、この歳で本格的に海で泳ぐようなこともないだろうし、いいか。","korean":"그런데 난 사실 수영을 잘 못한다……\n뭐, 이 나이에 바다에서 본격적으로 헤엄칠 일도 없겠지만.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":545,"id":"com_11.ks#545","kind":"text","speaker":"水蓮","english":"","japanese":"「あんまり気乗りしない？」","korean":"「별로 안 내켜?」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":551,"id":"com_11.ks#551","kind":"text","speaker":"名前","english":"","japanese":"「いや、行くよ。泳ぎは苦手だけど、\n浜辺でのんびりくつろぐのは好きだからさ」","korean":"「아냐, 갈래. 수영은 못해도\n해변에서 느긋하게 쉬는 건 좋아하거든.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":557,"id":"com_11.ks#557","kind":"text","speaker":"名前","english":"","japanese":"「それに、あの浜辺って、子供の頃よく一緒に遊んだ場所だよね？」","korean":"「그리고 그 해변, 어릴 때 우리 같이 자주 놀던 데잖아?」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":564,"id":"com_11.ks#564","kind":"text","speaker":"水蓮","english":"","japanese":"「そうだよ。みんなで泳いだり、砂遊びしたりしたね、ふふふ」","korean":"「맞아. 다 같이 헤엄도 치고 모래놀이도 했지. 후후.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":571,"id":"com_11.ks#571","kind":"text","speaker":"紫苑","english":"","japanese":"「泳ぎに……じゃあ、水着……かぁ……」","korean":"「헤엄치러…… 그럼 수영복……이네……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":576,"id":"com_11.ks#576","kind":"text","speaker":"名前","english":"","japanese":"「ん？」","korean":"「응?」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":579,"id":"com_11.ks#579","kind":"text","speaker":"나레이션","english":"","japanese":"紫苑が、何か口の中でごにょごにょ言っている。","korean":"시온이 뭐라고 작은 소리로 중얼거린다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":588,"id":"com_11.ks#588","kind":"text","speaker":"紫苑","english":"","japanese":"「まあ、お姉ちゃんが行きたいって言うんなら、いいけど……\n別に、泳ぐくらい……水着くらい……」","korean":"「뭐, 언니가 가고 싶으면 괜찮아……\n수영 정도야…… 수영복쯤이야……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":595,"id":"com_11.ks#595","kind":"text","speaker":"水蓮","english":"","japanese":"「じゃあ、決定！　お昼が済んだら、みんなで海に行きましょ」","korean":"「그럼 결정! 점심 다 먹고 같이 바다에 가자.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":603,"id":"com_11.ks#603","kind":"text","speaker":"水蓮","english":"","japanese":"「、うちのお父さんが昔使ってた水着でも大丈夫？」","korean":"「우리 아빠가 예전에 입던 수영복이라도 괜찮겠어?」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":608,"id":"com_11.ks#608","kind":"text","speaker":"名前","english":"","japanese":"「あっ……そうだ、水着持ってきてなかったんだ。\nうん、全然大丈夫だから、貸して貰えると助かるよ」","korean":"「아…… 맞다, 나 수영복 안 가져왔지.\n응, 괜찮아. 빌려주면 고맙지.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":613,"id":"com_11.ks#613","kind":"text","speaker":"나레이션","english":"","japanese":"そういえば、そうだった。","korean":"그러고 보니 정말 그랬다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":616,"id":"com_11.ks#616","kind":"text","speaker":"나레이션","english":"","japanese":"ぼくは、この美しい海に囲まれた島に来るというのに、\n水着すら持ってきていなかった。","korean":"이렇게 멋진 바다에 둘러싸인 섬까지 오면서 수영복 한 벌도 챙기지 않았다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":620,"id":"com_11.ks#620","kind":"text","speaker":"나레이션","english":"","japanese":"本当に行き当たりばったり、計画性のない旅だ。","korean":"정말 아무 계획 없이 발 닿는 대로 온 여행이다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":648,"id":"com_11.ks#648","kind":"text","speaker":"名前","english":"","japanese":"「おお……」","korean":"「우와……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":651,"id":"com_11.ks#651","kind":"text","speaker":"나레이션","english":"","japanese":"懐かしい、どこまでも青く澄んだ美しい海を\n目の前にして、思わず声が出てしまう。","korean":"추억 속 그대로, 끝없이 파랗고 맑은 바다가 눈앞에 펼쳐지자 나도 모르게 감탄이 나온다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":655,"id":"com_11.ks#655","kind":"text","speaker":"나레이션","english":"","japanese":"昼食後、水着やタオル、飲み物なんかを持って、\nぼくたちはこの浜辺へとやって来た。","korean":"점심을 먹고 수영복과 수건, 마실 것을 챙겨 해변으로 나왔다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":659,"id":"com_11.ks#659","kind":"text","speaker":"나레이션","english":"","japanese":"さぁ着替えよう、と思ったものの、よく考えたら開放してる場所でもないし、\n当然ここに更衣室なんてものはない。","korean":"자, 갈아입자 싶었는데 생각해 보니 누구나 오는 해변이 아니다.\n당연히 탈의실 같은 것도 없다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":663,"id":"com_11.ks#663","kind":"text","speaker":"나레이션","english":"","japanese":"浜辺につくまで、そのことを完全に失念していた。","korean":"해변에 도착할 때까지 그걸 까맣게 잊고 있었다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":667,"id":"com_11.ks#667","kind":"text","speaker":"名前","english":"","japanese":"「えっと……」","korean":"「어디 보자……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":670,"id":"com_11.ks#670","kind":"text","speaker":"나레이션","english":"","japanese":"どうしようか。","korean":"어떻게 하지.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":673,"id":"com_11.ks#673","kind":"text","speaker":"나레이션","english":"","japanese":"ぼくだけなら、子供の頃みたいにさっさと上を脱いでズボンも脱いで、\n腰にタオルを巻いて着替えてもいいんだけど──","korean":"나 혼자였으면 어릴 때처럼 윗옷도 바지도 후딱 벗고\n허리에 수건을 둘러 갈아입으면 되지만……","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":681,"id":"com_11.ks#681","kind":"text","speaker":"紫苑","english":"","japanese":"「…………」","korean":"「…………」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":689,"id":"com_11.ks#689","kind":"text","speaker":"名前","english":"","japanese":"「ええっ！？」","korean":"「뭐야?!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":692,"id":"com_11.ks#692","kind":"text","speaker":"나레이션","english":"","japanese":"二人がいるからなぁ、と気になって彼女たちの方を\n振り返ると、紫苑がいきなりバッと服を脱いだ。","korean":"둘이 있어서 어떻게 하나 싶어 뒤를 돌아봤더니, 시온이 갑자기 휙 옷을 벗었다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":697,"id":"com_11.ks#697","kind":"text","speaker":"名前","english":"","japanese":"「し、紫苑っ！？　なに……を……？」","korean":"「시, 시온아?! 뭐, 뭐 하는……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":700,"id":"com_11.ks#700","kind":"text","speaker":"나레이션","english":"","japanese":"突然の事態にものすごくびっくりして、\n思わず目が釘付けになったぼくだけど……","korean":"갑작스러운 일에 너무 놀라 나도 모르게 눈이 휘둥그레졌는데……","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":708,"id":"com_11.ks#708","kind":"text","speaker":"紫苑","english":"","japanese":"「……な、何よ、じろじろ見て……」","korean":"「……뭐, 뭐야. 그렇게 빤히 보고……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":712,"id":"com_11.ks#712","kind":"text","speaker":"名前","english":"","japanese":"「ご、ごめん……服の下に水着着てたんだね、子供の頃みたいに……」","korean":"「미, 미안…… 옷 밑에 수영복 입고 왔구나. 어릴 때처럼……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":718,"id":"com_11.ks#718","kind":"text","speaker":"紫苑","english":"","japanese":"「そりゃそうよ。更衣室なんてないんだから」","korean":"「당연하지. 탈의실이 없잖아.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":723,"id":"com_11.ks#723","kind":"text","speaker":"名前","english":"","japanese":"「だよね……」","korean":"「그렇지……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":726,"id":"com_11.ks#726","kind":"text","speaker":"나레이션","english":"","japanese":"びっくりした、ほんとびっくりした。\nでもさすがに裸になったりはしなかったか。","korean":"놀랐다. 정말 놀랐다.\n그래도 맨몸이 된 건 아니구나.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":730,"id":"com_11.ks#730","kind":"text","speaker":"나레이션","english":"","japanese":"うん、よかった。別にちょっとだけがっかりとかはしてない。","korean":"그래, 다행이다. 뭐, 조금 아쉽다거나 그런 건 아니다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":733,"id":"com_11.ks#733","kind":"text","speaker":"나레이션","english":"","japanese":"……けど、帰りはどうするんだろう。\n下着とかは持ってきてるんだろうか。","korean":"……그런데 돌아갈 땐 어쩌려나.\n갈아입을 속옷도 가져왔을까.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":737,"id":"com_11.ks#737","kind":"text","speaker":"나레이션","english":"","japanese":"確か子供の頃、紫苑は濡れた水着はそのまま、身体をパパッとタオルで拭いて、\nそのまま帰ってた気がするから、今日もそのやり方で？","korean":"어릴 때 시온은 젖은 수영복을 그대로 입고 몸만 수건으로 대충 닦고 돌아갔던 것 같은데,\n오늘도 그렇게 하려나?","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":742,"id":"com_11.ks#742","kind":"text","speaker":"名前","english":"","japanese":"「ぼ、ぼくも着替えようかな……」","korean":"「나, 나도 갈아입을까……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":745,"id":"com_11.ks#745","kind":"text","speaker":"나레이션","english":"","japanese":"多分、水蓮姉さんも紫苑と同じような感じで、\nすでに水着に着替えてるだろうから――","korean":"스이렌 누나도 시온이처럼 이미 수영복을 안에 입고 왔을 테니……","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":754,"id":"com_11.ks#754","kind":"text","speaker":"水蓮","english":"","japanese":"「ふふんふ～、ふふふふ～ん……」","korean":"「흐흥흥~ 흐흐흠~……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":761,"id":"com_11.ks#761","kind":"text","speaker":"名前","english":"","japanese":"「えっ……えっ！？」","korean":"「어…… 어어?!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":766,"id":"com_11.ks#766","kind":"text","speaker":"紫苑","english":"","japanese":"「ちょ、お姉ちゃん！？」","korean":"「잠깐, 언니?!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":770,"id":"com_11.ks#770","kind":"text","speaker":"나레이션","english":"","japanese":"水蓮姉さんは、なぜか脱いでいた。しかも水着じゃない。","korean":"웬일인지 스이렌 누나는 옷을 벗고 있었다. 수영복 차림도 아니다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":778,"id":"com_11.ks#778","kind":"text","speaker":"나레이션","english":"","japanese":"見事なプロポーションの身体を包む、大人っぽい下着。\nこう、清楚でありつつもセクシーな感じで、すごく色っぽい。","korean":"균형 잡힌 몸을 감싸는 어른스러운 속옷.\n단정해 보이면서도 묘하게 눈길을 끈다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":782,"id":"com_11.ks#782","kind":"text","speaker":"나레이션","english":"","japanese":"……もしかして、下着を水着代わりにするんだろうか。\nまさか、このまま泳いで……？","korean":"……설마 속옷을 수영복 대신 입으려는 건가.\n이대로 물에 들어갈 생각은 아니겠지……?","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":797,"id":"com_11.ks#797","kind":"text","speaker":"紫苑","english":"","japanese":"「変態！　変態っ、見るなーっ！」","korean":"「변태! 이 변태야, 보지 마!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":804,"id":"com_11.ks#804","kind":"text","speaker":"名前","english":"","japanese":"「そ、そんなこと言われてもっ……」","korean":"「그, 그렇게 말해도……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":807,"id":"com_11.ks#807","kind":"text","speaker":"나레이션","english":"","japanese":"見るなと言われても、目の前でこれだ。","korean":"보지 말라지만 바로 눈앞에서 벌어진 일이다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":810,"id":"com_11.ks#810","kind":"text","speaker":"나레이션","english":"","japanese":"しかも、慌てて視線を逸らしたところで、あの見事なボディと\n色っぽい下着姿は既に脳裏に焼き付いてしまっている。","korean":"게다가 급히 눈을 돌려 봤자 이미 그 눈에 띄는 몸매와 속옷 차림은 머릿속에 선명하게 남아 버렸다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":818,"id":"com_11.ks#818","kind":"text","speaker":"紫苑","english":"","japanese":"「お、お姉ちゃん、なんで下に水着着てないの！？\nそれか、せめてバスタオルで隠して着替えるとか……！！」","korean":"「어, 언니, 왜 안에 수영복을 안 입고 왔어?!\n아니면 큰 수건으로 좀 가리고 갈아입든가……!!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":827,"id":"com_11.ks#827","kind":"text","speaker":"水蓮","english":"","japanese":"「え？　別にいいじゃない、家族でしょ？\n弟や妹の前で着替えるのなんて、普通だよね？」","korean":"「응? 뭐 어때. 우리 가족이잖아.\n동생들 앞에서 옷 갈아입는 게 그렇게 이상한가?」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":834,"id":"com_11.ks#834","kind":"text","speaker":"紫苑","english":"","japanese":"「いや、従弟でしょ！？　それに、みんな子供じゃないんだしっ……」","korean":"「가족이라도 사촌이잖아?! 다들 이제 어린애도 아니고……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":840,"id":"com_11.ks#840","kind":"text","speaker":"紫苑","english":"","japanese":"「そもそも、弟とは結婚できないんだから、\n大人になったら裸見せちゃダメなの！」","korean":"「애초에 친동생이랑은 결혼 못 하잖아.\n다 컸으면 맨몸을 보여 주면 안 되는 거야!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":846,"id":"com_11.ks#846","kind":"text","speaker":"名前","english":"","japanese":"「……ええ……？」","korean":"「……뭐라고……?」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":852,"id":"com_11.ks#852","kind":"text","speaker":"나레이션","english":"","japanese":"弟でも弟みたいな扱いの親戚でも、とりあえず大人になったら\nお互いに裸は見せちゃダメ、だけでいいと思うんだけど。","korean":"친동생이든 동생처럼 지내는 친척이든, 다 컸으니 서로 맨몸을 보여 주면 안 된다는 말이면\n충분할 것 같은데.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":860,"id":"com_11.ks#860","kind":"text","speaker":"水蓮","english":"","japanese":"「今日も暑いね。ちゃんと日焼け止めは塗っておかないとね……」","korean":"「오늘도 덥네. 선크림은 잘 발라 둬야지……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":865,"id":"com_11.ks#865","kind":"text","speaker":"名前","english":"","japanese":"「うわっ……」","korean":"「우앗……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":873,"id":"com_11.ks#873","kind":"text","speaker":"紫苑","english":"","japanese":"「わあっ……ちょっと、見るなって言ってるでしょー！？\nお姉ちゃん、さっさと着て、さっさと！！」","korean":"「으악…… 보지 말라고 했잖아?!\n언니, 얼른 입어! 빨리!!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":879,"id":"com_11.ks#879","kind":"text","speaker":"名前","english":"","japanese":"「見てないっ、見てないよ！！\nぼ、ぼく、あっちで着替えてくるから……！！」","korean":"「안 봤어, 안 봤다고!!\n나, 난 저쪽 가서 갈아입고 올게……!!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":883,"id":"com_11.ks#883","kind":"text","speaker":"나레이션","english":"","japanese":"ついには、水蓮姉さんが素っ裸になるのまで視界の隅に見えてしまった。","korean":"결국 시야 한구석에 스이렌 누나가 알몸이 되는 것까지 들어오고 말았다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":886,"id":"com_11.ks#886","kind":"text","speaker":"나레이션","english":"","japanese":"これはもうヤバすぎるので、ぼくは慌てて\nあちらの岩場の陰を目指して走り出した。","korean":"이대로는 정말 위험하다. 서둘러 저편 바위 뒤로 뛰어갔다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":902,"id":"com_11.ks#902","kind":"text","speaker":"水蓮","english":"","japanese":"「別に、いいのになぁ……」","korean":"「뭐 어때서 그러지……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":908,"id":"com_11.ks#908","kind":"text","speaker":"紫苑","english":"","japanese":"「よくないでしょ……はぁぁ……」","korean":"「뭐 어떻긴…… 하아아……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":924,"id":"com_11.ks#924","kind":"text","speaker":"名前","english":"","japanese":"「はぁ……まいったな、これ……」","korean":"「하아…… 큰일이네, 이거……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":927,"id":"com_11.ks#927","kind":"text","speaker":"나레이션","english":"","japanese":"股間が、熱い。","korean":"아랫도리가 뜨겁다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":930,"id":"com_11.ks#930","kind":"text","speaker":"나레이션","english":"","japanese":"タオルと水着で隠しながら移動してるけど、\nギンギンに勃起していてもう限界だ。","korean":"수건과 수영복으로 가리고 왔지만, 아래가 잔뜩 서 있다. 이대로는 더 못 버틴다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":934,"id":"com_11.ks#934","kind":"text","speaker":"나레이션","english":"","japanese":"岩場に身を隠し、なんとか心身を落ち着けながら着替えるしかない。","korean":"바위 뒤에 몸을 숨긴 채 어떻게든 마음을 진정시키고 갈아입어야 한다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":938,"id":"com_11.ks#938","kind":"text","speaker":"名前","english":"","japanese":"「すぅ……はぁ…………はぁぁ……」","korean":"「스읍…… 하아………… 하아아……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":941,"id":"com_11.ks#941","kind":"text","speaker":"나레이션","english":"","japanese":"着替えつつ、岩とか砂を凝視して深呼吸する。\n無機物に性的興奮を覚える変態みたいで嫌だな、これ……。","korean":"옷을 갈아입으며 바위나 모래만 뚫어져라 보고 숨을 깊게 쉰다.\n이러고 있으니 돌멩이 보고 흥분하는 변태라도 된 것 같아서 싫다……","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":953,"id":"com_11.ks#953","kind":"text","speaker":"나레이션","english":"","japanese":"瞼に焼きついた水蓮姉さんの裸が岩に置き換わる頃、\n股間もやっと落ち着いてきたから、ぼくは二人の待つ場所へ戻ることにした。","korean":"눈에 아른거리던 스이렌 누나의 알몸이 바위로 바뀔 즈음, 아래도 겨우 진정됐다.\n이제 두 사람이 있는 곳으로 돌아가기로 했다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":957,"id":"com_11.ks#957","kind":"text","speaker":"나레이션","english":"","japanese":"ちょっぴりもったいないような気もしたけど。","korean":"조금 아쉽다는 생각도 들었지만.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":972,"id":"com_11.ks#972","kind":"text","speaker":"水蓮","english":"","japanese":"「おかえり。海に入る前には、準備運動してね」","korean":"「왔어? 바다에 들어가기 전에 준비운동부터 해.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":981,"id":"com_11.ks#981","kind":"text","speaker":"紫苑","english":"","japanese":"「、男のくせに着替えに時間かかりすぎじゃない？」","korean":"「남자가 옷 갈아입는 데 뭐가 그렇게 오래 걸려?」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":986,"id":"com_11.ks#986","kind":"text","speaker":"名前","english":"","japanese":"「あ、うん、ごめん……」","korean":"「아, 응. 미안……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":989,"id":"com_11.ks#989","kind":"text","speaker":"나레이션","english":"","japanese":"せっかく勃起が治まったというのに、そこには水着姿の\n美人姉妹が待っていた。まあ、当然なんだけど。","korean":"기껏 진정시키고 돌아왔는데 두 자매가 수영복 차림으로 기다리고 있었다. 뭐, 당연하지만.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":993,"id":"com_11.ks#993","kind":"text","speaker":"나레이션","english":"","japanese":"まぶしい太陽のもと、惜しげもなく魅力的な肢体を晒している。\n二人ともビキニタイプの水着で、思わず視線が吸い寄せられてしまう。","korean":"눈부신 햇볕 아래 두 사람의 몸매가 그대로 드러난다.\n둘 다 비키니를 입고 있어서 나도 모르게 눈길이 간다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":999,"id":"com_11.ks#999","kind":"text","speaker":"水蓮","english":"","japanese":"「ふふふ」","korean":"「후후후.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1004,"id":"com_11.ks#1004","kind":"text","speaker":"紫苑","english":"","japanese":"「ん……」","korean":"「음……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1008,"id":"com_11.ks#1008","kind":"text","speaker":"名前","english":"","japanese":"「……っ……」","korean":"「……읏……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1011,"id":"com_11.ks#1011","kind":"text","speaker":"나레이션","english":"","japanese":"落ち着いていながらも匂い立つような色香があり、\nなんとも冒しがたい雰囲気を漂わせる水蓮姉さん。","korean":"스이렌 누나는 차분한데도 묘하게 매혹적이다.\n함부로 다가가기 어려운 분위기마저 느껴진다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1015,"id":"com_11.ks#1015","kind":"text","speaker":"나레이션","english":"","japanese":"そして、軽くストレッチをしているため、身体のラインや動きが見えて、\nなんとも目のやり場に困ってしまう状態の紫苑。","korean":"시온은 가볍게 몸을 풀고 있어서 몸의 선이 움직임을 따라 드러난다.\n도무지 어디에 눈을 둬야 할지 모르겠다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1019,"id":"com_11.ks#1019","kind":"text","speaker":"나레이션","english":"","japanese":"ぼくは、すっかり二人の肢体に見とれてしまっている。","korean":"나도 모르게 두 사람을 한참 바라보고 있었다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1029,"id":"com_11.ks#1029","kind":"text","speaker":"水蓮","english":"","japanese":"「ふう……荷物は日陰に置いて、っと……」","korean":"「후우…… 짐은 그늘에 두고……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1032,"id":"com_11.ks#1032","kind":"text","speaker":"나레이션","english":"","japanese":"水蓮姉さんは、浜辺で持ってきた荷物をまとめたり、\n飲み物の入ったクーラーボックスを整理しているようだ。","korean":"스이렌 누나는 해변에 가져온 짐을 모으고,\n마실 게 든 아이스박스도 정리하는 모양이다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1037,"id":"com_11.ks#1037","kind":"text","speaker":"名前","english":"","japanese":"「…………」","korean":"「…………」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1040,"id":"com_11.ks#1040","kind":"text","speaker":"나레이션","english":"","japanese":"本当に、何をしてても絵になるというか、すっごく綺麗だ。\n水着も結構大胆な感じで、大人っぽい感じがとても似合っている。","korean":"정말 뭘 해도 그림 같다. 보고 있으면 감탄만 나온다.\n꽤 대담한 수영복도 어른스러운 누나한테 잘 어울린다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1051,"id":"com_11.ks#1051","kind":"text","speaker":"水蓮","english":"","japanese":"「ん？　どうしたの？」","korean":"「응? 왜 그래?」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1055,"id":"com_11.ks#1055","kind":"text","speaker":"名前","english":"","japanese":"「はっ……」","korean":"「앗……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1058,"id":"com_11.ks#1058","kind":"text","speaker":"나레이션","english":"","japanese":"見とれてじーっと眺めていたら、優しく微笑み返されてしまった。","korean":"나도 모르게 넋 놓고 보고 있었더니, 누나가 다정하게 웃어 준다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1061,"id":"com_11.ks#1061","kind":"text","speaker":"나레이션","english":"","japanese":"ばつが悪いが、それ以上に気恥ずかしい。","korean":"민망한 것도 민망한데, 괜히 더 쑥스러워진다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1065,"id":"com_11.ks#1065","kind":"text","speaker":"水蓮","english":"","japanese":"「どうかな、お姉ちゃんの水着……\n久しぶりだよね、一緒に海で過ごすのも」","korean":"「누나 수영복은 어때?\n같이 바다에 온 것도 정말 오랜만이지.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1070,"id":"com_11.ks#1070","kind":"text","speaker":"名前","english":"","japanese":"「じろじろ見ちゃってごめん……昔とは色々と違いすぎて、\nちょっと緊張しちゃうけど……」","korean":"「빤히 봐서 미안해…… 옛날이랑 너무 달라서 그런지 좀 떨려.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1075,"id":"com_11.ks#1075","kind":"text","speaker":"名前","english":"","japanese":"「ええと、水蓮姉さんの水着、その……す、すごく似合ってるよ。\n大人っぽい雰囲気もあって、綺麗で……」","korean":"「그게, 스이렌 누나 수영복…… 저, 정말 잘 어울려.\n어른스러운 느낌도 나고, 예뻐서……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1086,"id":"com_11.ks#1086","kind":"text","speaker":"水蓮","english":"","japanese":"「わあ、嬉しい……ふふ、ありがとう」","korean":"「와, 좋다…… 후후, 고마워.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1090,"id":"com_11.ks#1090","kind":"text","speaker":"水蓮","english":"","japanese":"「そんな風に褒められると、すごく嬉しいな。綺麗、だなんて」","korean":"「그렇게 칭찬해 주니까 정말 기쁘네. 예쁘다니.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1094,"id":"com_11.ks#1094","kind":"text","speaker":"名前","english":"","japanese":"「なら良かったよ……けど、なんというか、さすがに照れくさいね……」","korean":"「그럼 다행인데…… 역시 직접 말하니까 좀 쑥스럽네……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1097,"id":"com_11.ks#1097","kind":"text","speaker":"나레이션","english":"","japanese":"嬉しそうに、まぶしいほどの笑顔を向けられて、\nぼくは思わず目をそらした。本当に、まぶし過ぎる。","korean":"누나가 기뻐서 눈부시게 활짝 웃는다.\n나도 모르게 시선을 피했다. 정말 눈부실 만큼 환했다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1101,"id":"com_11.ks#1101","kind":"text","speaker":"나레이션","english":"","japanese":"が、いくら水蓮姉さんが許してくれるからって、\n女の人の水着姿をずーっと無遠慮にじろじろ見るのはまずいだろう。","korean":"그래도 스이렌 누나가 괜찮다고 해서 수영복 입은 사람을 염치없이 계속 빤히 보면 안 될 것 같다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1106,"id":"com_11.ks#1106","kind":"text","speaker":"水蓮","english":"","japanese":"「ふふっ」","korean":"「후후.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1110,"id":"com_11.ks#1110","kind":"text","speaker":"名前","english":"","japanese":"「うっ……」","korean":"「윽……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1113,"id":"com_11.ks#1113","kind":"text","speaker":"나레이션","english":"","japanese":"顔の向きを変えたぼくは、自然と紫苑の方を向くこととなった。","korean":"고개를 돌리자 자연스레 시온 쪽을 보게 됐다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1123,"id":"com_11.ks#1123","kind":"text","speaker":"紫苑","english":"","japanese":"「んんー、と……はあ、んんー……」","korean":"「으음, 자…… 하아, 으음……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1127,"id":"com_11.ks#1127","kind":"text","speaker":"名前","english":"","japanese":"「……あ……」","korean":"「……아……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1130,"id":"com_11.ks#1130","kind":"text","speaker":"나레이션","english":"","japanese":"こっちはこっちで、またしても目に毒というか……すごい眺めだった。","korean":"시온 쪽으로 고개를 돌린 게 실수였나 보다…… 여기도 눈을 어디에 둬야 할지 모르겠다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1133,"id":"com_11.ks#1133","kind":"text","speaker":"나레이션","english":"","japanese":"紫苑は真剣な表情で、しっかりとストレッチで身体をほぐしている。\n泳ぐ気満々といった様子だ。","korean":"시온은 진지한 표정으로 꼼꼼히 몸을 풀고 있다.\n당장이라도 물에 뛰어들 기세다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1137,"id":"com_11.ks#1137","kind":"text","speaker":"나레이션","english":"","japanese":"ただ、布地面積的には下着と変わらない水着のせいで、\n嫌でもそのプロポーションが強調されてしまう。","korean":"다만 속옷만큼이나 천이 적은 수영복이라 움직일 때마다 몸의 선이 도드라진다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1141,"id":"com_11.ks#1141","kind":"text","speaker":"나레이션","english":"","japanese":"ぐっと開かれる脇や、脚を開く動作で見える内ももなどなど……\n健康的な肌がこれでもかと視界に飛び込んできてしまう。","korean":"크게 팔을 들면 겨드랑이가 보이고, 다리를 벌리면 허벅지 안쪽이 드러난다.\n건강한 살결이 자꾸 눈에 들어온다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1145,"id":"com_11.ks#1145","kind":"text","speaker":"나레이션","english":"","japanese":"普段は見えない部分が見えることに、すごくドキドキしてしまう。","korean":"평소에는 볼 일이 없는 모습이라 괜히 심장이 뛴다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1149,"id":"com_11.ks#1149","kind":"text","speaker":"紫苑","english":"","japanese":"「よっ、と……」","korean":"「으쌰……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1153,"id":"com_11.ks#1153","kind":"text","speaker":"名前","english":"","japanese":"「…………」","korean":"「…………」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1156,"id":"com_11.ks#1156","kind":"text","speaker":"나레이션","english":"","japanese":"引き締まった健康的な肢体に、形のよい胸も、\nしっかりと張り出していて、女性的な魅力も強く感じられる。","korean":"몸은 탄탄하고 균형이 잡혀 있다. 가슴의 선도 또렷해서,\n그냥 건강해 보이는 것만으로는 설명이 안 되는 매력이 있다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1160,"id":"com_11.ks#1160","kind":"text","speaker":"나레이션","english":"","japanese":"いけないと思いつつ、ぼくはまたしても目を奪われてしまった。","korean":"보면 안 된다고 생각하면서도 결국 또 눈길을 빼앗겼다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1164,"id":"com_11.ks#1164","kind":"text","speaker":"紫苑","english":"","japanese":"「んっ、んっ、と……最近身体硬くなったかな、気をつけないと……\nふう、ううっ……」","korean":"「음, 으음…… 요즘 몸이 좀 굳었나. 신경 써야겠네……\n후우, 으으……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1169,"id":"com_11.ks#1169","kind":"text","speaker":"名前","english":"","japanese":"「……っ……」","korean":"「……읏……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1172,"id":"com_11.ks#1172","kind":"text","speaker":"나레이션","english":"","japanese":"どうしても、目が離せない。\nその場で固まったように、じっと見つめてしまって――","korean":"도저히 눈을 뗄 수가 없다.\n그 자리에 얼어붙은 것처럼 한참 바라보고 있는데……","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1183,"id":"com_11.ks#1183","kind":"text","speaker":"紫苑","english":"","japanese":"「あ……」","korean":"「아……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1187,"id":"com_11.ks#1187","kind":"text","speaker":"名前","english":"","japanese":"「あっ……」","korean":"「앗……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1190,"id":"com_11.ks#1190","kind":"text","speaker":"나레이션","english":"","japanese":"ぼくの視線に紫苑が気づいたようだ。","korean":"시온이 내 시선을 알아챈 모양이다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1193,"id":"com_11.ks#1193","kind":"text","speaker":"나레이션","english":"","japanese":"はっとした表情で、ぼくの顔と自分の身体を交互に眺めている。","korean":"흠칫 놀란 얼굴로 내 얼굴과 자기 몸을 번갈아 본다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1197,"id":"com_11.ks#1197","kind":"text","speaker":"紫苑","english":"","japanese":"「……っ……」","korean":"「……읏……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1201,"id":"com_11.ks#1201","kind":"text","speaker":"名前","english":"","japanese":"「う……」","korean":"「으……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1204,"id":"com_11.ks#1204","kind":"text","speaker":"나레이션","english":"","japanese":"不味い……ぼくが紫苑の身体をじっくり眺めていたことに、\nばっちり気付いてしまっている。","korean":"큰일이다…… 내가 시온을 한참 바라보고 있었다는 걸 제대로 들켰다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1215,"id":"com_11.ks#1215","kind":"text","speaker":"紫苑","english":"","japanese":"「何よ？　貧相な身体なんて見て楽しいの？」","korean":"「뭐야? 이런 볼품없는 몸을 보니까 재밌어?」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1219,"id":"com_11.ks#1219","kind":"text","speaker":"名前","english":"","japanese":"「へ？」","korean":"「어?」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1223,"id":"com_11.ks#1223","kind":"text","speaker":"紫苑","english":"","japanese":"「お姉ちゃんと比べたら、貧相だし……\n見てても楽しくなんてないでしょ……」","korean":"「언니한테 비하면 볼품없잖아……\n봐 봤자 재미도 없을 텐데……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1228,"id":"com_11.ks#1228","kind":"text","speaker":"名前","english":"","japanese":"「ええっ！？　いや、ぼくはその、紫苑も水着が似合ってて、\n綺麗だと思って……」","korean":"「뭐?! 아니, 그게, 시온이도 수영복이 잘 어울리니까\n예쁘다고 생각해서……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1239,"id":"com_11.ks#1239","kind":"text","speaker":"紫苑","english":"","japanese":"「いいわよ、別に……お世辞なんて」","korean":"「됐어, 그런 빈말은……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1243,"id":"com_11.ks#1243","kind":"text","speaker":"名前","english":"","japanese":"「いや、お世辞じゃないって……！　すごく、その……\nしゅっとしてて、しなやかっていうのかな……」","korean":"「빈말이 아니라니까……! 너는 그, 되게……\n늘씬하고 선이 곱다고 해야 하나……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1248,"id":"com_11.ks#1248","kind":"text","speaker":"紫苑","english":"","japanese":"「……やっぱり……胸がないって言いたいんでしょ、\nしゅっとした棒切れみたいな体型、って」","korean":"「……역시…… 가슴 없다는 소리잖아.\n막대기처럼 삐쩍 말랐다는 거지.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1253,"id":"com_11.ks#1253","kind":"text","speaker":"名前","english":"","japanese":"「なんでそうなるの！　受け取り方が悪意的すぎるよ！\n手足もすらっとして綺麗で、水着も可愛い感じでいいなっていうか……！」","korean":"「왜 그렇게 받아들여! 너무 나쁘게만 듣잖아!\n팔다리도 길고 예쁘고, 수영복도 귀여워서 잘 어울린다는 말이야……!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1257,"id":"com_11.ks#1257","kind":"text","speaker":"나레이션","english":"","japanese":"なんだかもう、どう言えばちゃんと伝わるのかわからず、\nぼくは必死に言葉を紡ぐ。","korean":"어떻게 말해야 내 뜻이 제대로 전해질지 몰라,\n나는 어떻게든 할 말을 찾아낸다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1261,"id":"com_11.ks#1261","kind":"text","speaker":"나레이션","english":"","japanese":"紫苑に、自分を卑下するような受け取り方をして欲しくない。\n正直、女性の褒め方に自信はないが、ここはやらねばならない場面だ。","korean":"시온이 자기 자신을 깎아내리는 쪽으로 받아들이지는 않았으면 좋겠다.\n솔직히 칭찬을 잘할 자신은 없지만, 지금만큼은 제대로 말해야 한다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1266,"id":"com_11.ks#1266","kind":"text","speaker":"紫苑","english":"","japanese":"「…………」","korean":"「…………」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1270,"id":"com_11.ks#1270","kind":"text","speaker":"名前","english":"","japanese":"「つまり、紫苑には水蓮姉さんとは違った魅力があるってことなんだよ！\n可愛い感じの水着がより一層、紫苑の魅力を惹き立ててるっていうかさ……」","korean":"「그러니까 시온이한테는 스이렌 누나랑 다른 매력이 있다는 말이야!\n귀여운 수영복을 입으니까 시온이 매력이 더 산다고 해야 하나……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1281,"id":"com_11.ks#1281","kind":"text","speaker":"紫苑","english":"","japanese":"「み、魅力があるって、何、それ……そ、そう、そうなんだ……」","korean":"「매, 매력이 있다고? 뭐야, 그게…… 그, 그래. 그렇구나……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1284,"id":"com_11.ks#1284","kind":"text","speaker":"나레이션","english":"","japanese":"紫苑は、ぼくから視線をそらして途切れ途切れに\nごにょごにょ言い始めた。","korean":"시온이 눈을 피하며 말을 띄엄띄엄 중얼거리기 시작했다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1289,"id":"com_11.ks#1289","kind":"text","speaker":"名前","english":"","japanese":"「紫苑……」","korean":"「시온아……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1292,"id":"com_11.ks#1292","kind":"text","speaker":"나레이션","english":"","japanese":"ぼくは、どうやらぼくの言葉がようやく届いてくれたのか、\nおとなしくなった紫苑にほっとしたのだが――","korean":"이제야 내 말이 전해진 건가. 시온이 잠잠해져서 마음이 놓였는데……","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1297,"id":"com_11.ks#1297","kind":"text","speaker":"紫苑","english":"","japanese":"「くっ……！」","korean":"「윽……!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1301,"id":"com_11.ks#1301","kind":"text","speaker":"名前","english":"","japanese":"「え？」","korean":"「어?」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1311,"id":"com_11.ks#1311","kind":"text","speaker":"紫苑","english":"","japanese":"「べ、別に、見るなとは言わないけど！\nそうやってじーっと見るのって、デリカシーなさすぎ！」","korean":"「보, 보지 말라는 건 아닌데!\n그렇게 빤히 쳐다보는 건 너무 눈치 없잖아!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1316,"id":"com_11.ks#1316","kind":"text","speaker":"名前","english":"","japanese":"「ご、ごめん……」","korean":"「미, 미안……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1320,"id":"com_11.ks#1320","kind":"text","speaker":"紫苑","english":"","japanese":"「も、もういいっ……泳いでくるから……！！」","korean":"「이, 이제 됐어…… 난 수영할 거야……!!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1331,"id":"com_11.ks#1331","kind":"text","speaker":"名前","english":"","japanese":"「あっ……」","korean":"「아……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1334,"id":"com_11.ks#1334","kind":"text","speaker":"나레이션","english":"","japanese":"急にキッとこちらをにらみつけたと思えば、\n紫苑はストレッチを切り上げて海へと向かっていく。","korean":"시온은 갑자기 매섭게 한 번 노려보더니, 준비운동을 그만두고 바다 쪽으로 간다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1345,"id":"com_11.ks#1345","kind":"text","speaker":"名前","english":"","japanese":"「はぁ……」","korean":"「하아……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1348,"id":"com_11.ks#1348","kind":"text","speaker":"나레이션","english":"","japanese":"怒らせちゃったかな、とうなだれつつ、ぼくはその場に座り込む。","korean":"괜히 화나게 했나 싶어 고개를 떨군 채 그 자리에 주저앉는다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1351,"id":"com_11.ks#1351","kind":"text","speaker":"나레이션","english":"","japanese":"熱い砂の感触が、足や尻に伝わってくる。\nこんな感覚を味わうのも、何年ぶりだろうか。","korean":"뜨거운 모래가 다리랑 엉덩이에 닿는다.\n이런 느낌도 몇 년 만이지.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1358,"id":"com_11.ks#1358","kind":"text","speaker":"水蓮","english":"","japanese":"「」","korean":"「」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1362,"id":"com_11.ks#1362","kind":"text","speaker":"名前","english":"","japanese":"「ん？」","korean":"「응?」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1365,"id":"com_11.ks#1365","kind":"text","speaker":"나레이션","english":"","japanese":"背後から足音もなくそっと、水蓮姉さんが近づいてきたようだ。","korean":"발소리도 없이 스이렌 누나가 등 뒤로 살며시 다가온 모양이다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1372,"id":"com_11.ks#1372","kind":"text","speaker":"水蓮","english":"","japanese":"「大丈夫だよ、心配しないで」","korean":"「괜찮아, 걱정하지 마.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1377,"id":"com_11.ks#1377","kind":"text","speaker":"名前","english":"","japanese":"「ありがと……でも、紫苑を怒らせちゃって……」","korean":"「고마워…… 그래도 시온이를 화나게 했잖아……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1384,"id":"com_11.ks#1384","kind":"text","speaker":"紫苑","english":"","japanese":"「……っ……」","korean":"「……읏……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1389,"id":"com_11.ks#1389","kind":"text","speaker":"名前","english":"","japanese":"「あ……」","korean":"「아……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1392,"id":"com_11.ks#1392","kind":"text","speaker":"나레이션","english":"","japanese":"振り向くと、紫苑はまだ海には入っておらず、\nぼくのそばにいた。","korean":"돌아보니 시온도 아직 물에 들어가지 않고 내 곁에 와 있었다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1396,"id":"com_11.ks#1396","kind":"text","speaker":"나레이션","english":"","japanese":"姉妹して、ぼくの背後からそーっと近づいてきていたのか。","korean":"두 자매가 나란히 등 뒤로 살금살금 다가왔던 건가.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1402,"id":"com_11.ks#1402","kind":"text","speaker":"紫苑","english":"","japanese":"「……別に、どうでもいいしっ……」","korean":"「……별로, 신경 안 쓰거든……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1407,"id":"com_11.ks#1407","kind":"text","speaker":"名前","english":"","japanese":"「紫苑……ごめん、不躾に見すぎてたよね……」","korean":"「시온아…… 미안해. 예의 없이 너무 빤히 봤지……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1414,"id":"com_11.ks#1414","kind":"text","speaker":"紫苑","english":"","japanese":"「だから、いいって、もう……」","korean":"「됐다고 했잖아, 정말……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1417,"id":"com_11.ks#1417","kind":"text","speaker":"나레이션","english":"","japanese":"なんだかんだ言いつつも、頬を赤らめそばにいてくれている。\nぼくを、遠ざけたいわけじゃない……みたいだ。","korean":"저렇게 말하면서도 뺨을 붉힌 채 곁에 있어 준다.\n나를 멀리하고 싶은 건…… 아닌 모양이다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1422,"id":"com_11.ks#1422","kind":"text","speaker":"나레이션","english":"","japanese":"じゃあさっきは、怒ってたんじゃなくて照れてたのかな、\nなんて、希望的観測を抱いてしまう。","korean":"그럼 아까는 화가 난 게 아니라 쑥스러웠던 걸까.\n나도 모르게 내게 좋은 쪽으로 해석하게 된다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1426,"id":"com_11.ks#1426","kind":"text","speaker":"나레이션","english":"","japanese":"だったらいいな、なんて苦笑をこぼし、改めてぼくは二人に向き合う。\n今度はできるだけさりげなく、二人の姿を視界に納めた。","korean":"그랬으면 좋겠다는 생각에 어색하게 웃으며 두 사람을 다시 마주 본다.\n이번에는 최대한 티 내지 않고.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1430,"id":"com_11.ks#1430","kind":"text","speaker":"나레이션","english":"","japanese":"……見たいと思ってしまうのはしょうがないにせよ、\n少しは慣れておかないと、せっかく海に来たのに申し訳ないもんな。","korean":"……눈길이 가는 건 어쩔 수 없다 해도 좀 익숙해져야지.\n모처럼 바다에 왔는데 계속 불편하게 할 순 없잖아.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1437,"id":"com_11.ks#1437","kind":"text","speaker":"水蓮","english":"","japanese":"「日差しも強いし、紫苑も水分補給はしっかりね」","korean":"「햇볕이 세니까 시온이도 물 꼭 챙겨 마셔.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1443,"id":"com_11.ks#1443","kind":"text","speaker":"紫苑","english":"","japanese":"「うん、わかった」","korean":"「응, 알았어.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1448,"id":"com_11.ks#1448","kind":"text","speaker":"名前","english":"","japanese":"「…………」","korean":"「…………」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1451,"id":"com_11.ks#1451","kind":"text","speaker":"나레이션","english":"","japanese":"凝視しないように注意しつつも、ぼくは改めてそれぞれの魅力を痛感する。","korean":"빤히 보지 않으려고 조심하면서도, 새삼 두 사람한테 각기 다른 매력이 있다는 걸 느낀다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1464,"id":"com_11.ks#1464","kind":"text","speaker":"나레이션","english":"","japanese":"大人びた美人で、スタイル抜群の水蓮姉さん。\n女性らしい曲線や体つきのメリハリって言えばいいのか。","korean":"스이렌 누나는 어른스러운 미인에 몸매도 눈에 띈다.\n곡선이 뚜렷하다고 해야 하나.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1468,"id":"com_11.ks#1468","kind":"text","speaker":"나레이션","english":"","japanese":"匂い立つような色気や艶みたいなものを感じて、\n直視していると、ちょっと変な気分になりそうだ。","korean":"가만있어도 매혹적인 분위기가 느껴져서,\n똑바로 보다간 나도 모르게 이상한 기분이 들 것 같다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1485,"id":"com_11.ks#1485","kind":"text","speaker":"나레이션","english":"","japanese":"紫苑は少し可愛さが強めな美人さんで、\n均整の取れた体つきのバランスもあって、思わず目を奪われてしまう。","korean":"시온은 귀여운 쪽에 가까운 미인이다.\n몸의 균형도 좋아서 나도 모르게 시선을 빼앗긴다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1491,"id":"com_11.ks#1491","kind":"text","speaker":"紫苑","english":"","japanese":"「…………っ」","korean":"「…………읏.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1494,"id":"com_11.ks#1494","kind":"text","speaker":"나레이션","english":"","japanese":"紫苑は、水蓮姉さんと自分を比べて卑下してるみたいだけど、\n違った魅力があって、こんなに可愛いんだからそんな必要はまるでないと思う。","korean":"시온은 스이렌 누나와 비교하면서 스스로를 낮추는 것 같지만,\n그렇게 비교할 필요가 없다. 저렇게 귀엽고 자기만의 매력도 있는데.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1498,"id":"com_11.ks#1498","kind":"text","speaker":"나레이션","english":"","japanese":"というか、水蓮姉さんが規格外側なだけで、紫苑も充分すぎるほど\nおっぱいあるよな……健康的な色気って感じがして良い。","korean":"애초에 스이렌 누나가 유난히 눈에 띄는 거지, 시온도 가슴이 작은 편은 아니다.\n건강해 보이면서도 묘하게 매력적이다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1504,"id":"com_11.ks#1504","kind":"text","speaker":"水蓮","english":"","japanese":"「」","korean":"「」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1515,"id":"com_11.ks#1515","kind":"text","speaker":"名前","english":"","japanese":"「はいっ！？」","korean":"「네?!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1518,"id":"com_11.ks#1518","kind":"text","speaker":"나레이션","english":"","japanese":"嗜好に耽っていたところでいきなり声をかけられて、\n思わずビクンと跳ね上がりそうになった。","korean":"그런 생각에 한창 빠져 있다가 누나가 갑자기 말을 걸어서,\n하마터면 펄쩍 뛸 뻔했다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1527,"id":"com_11.ks#1527","kind":"text","speaker":"水蓮","english":"","japanese":"「せっかくだし、みんなで遊びましょ！　子供の頃みたいに、ね？」","korean":"「모처럼 왔으니까 다 같이 놀자! 어릴 때처럼, 응?」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1531,"id":"com_11.ks#1531","kind":"text","speaker":"名前","english":"","japanese":"「そうだね、うん……せっかく来たんだもんね」","korean":"「그래, 응…… 모처럼 왔으니까.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1536,"id":"com_11.ks#1536","kind":"text","speaker":"紫苑","english":"","japanese":"「いいわよ、別に」","korean":"「난 뭐, 괜찮아.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1540,"id":"com_11.ks#1540","kind":"text","speaker":"나레이션","english":"","japanese":"ぼくは慌ててうなずき、紫苑も小さくうなずいた。","korean":"나는 급히 고개를 끄덕였다. 시온도 작게 고개를 끄덕인다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1543,"id":"com_11.ks#1543","kind":"text","speaker":"나레이션","english":"","japanese":"そしてぼくたちは海へと向かうのだった――","korean":"그렇게 우리는 물 쪽으로 향했다……","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1588,"id":"com_11.ks#1588","kind":"text","speaker":"名前","english":"","japanese":"「うわっぷ、うぷぷっ！」","korean":"「으악, 푸흡!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1594,"id":"com_11.ks#1594","kind":"text","speaker":"紫苑","english":"","japanese":"「あきれた、今でも泳ぎはダメなのね」","korean":"「기가 막혀. 아직도 수영은 영 못하는구나.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1599,"id":"com_11.ks#1599","kind":"text","speaker":"名前","english":"","japanese":"「い、犬かきみたいな感じでなら、\nしばらくは浮かべるんだけど……うぶっ……」","korean":"「개, 개헤엄이라도 치면 잠깐은 뜰 수 있는데…… 푸흡……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1603,"id":"com_11.ks#1603","kind":"text","speaker":"나레이션","english":"","japanese":"子供の時から泳ぎが苦手なのは元々なんだけど、さらに昔、\n海で溺れた経験があり、苦手意識が根付いてしまったんだと思う。","korean":"어릴 때부터 수영을 잘 못했다. 게다가 더 어렸을 때 바다에 빠진 적도 있어서, 그 뒤로 물이 더 무서워진 것 같다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1607,"id":"com_11.ks#1607","kind":"text","speaker":"나레이션","english":"","japanese":"一応、最低限は泳げるけど、平泳ぎとかクロールとか、\nきちんとした形での泳ぎは苦手だ。","korean":"어떻게든 헤엄은 칠 수 있지만 평영이나 자유형처럼 제대로 된 자세로는 잘 못한다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1611,"id":"com_11.ks#1611","kind":"text","speaker":"나레이션","english":"","japanese":"２５メートルくらいなら騙し騙しいけるけど、もちろん遠泳とかは無理。","korean":"25미터쯤은 어떻게든 가겠지만, 멀리 헤엄치는 건 당연히 무리다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1614,"id":"com_11.ks#1614","kind":"text","speaker":"나레이션","english":"","japanese":"海に入って遊んでたけど、浮き輪を離さなかったり\n不格好に崩れた犬かきしかできないぼくを見かねて、\n紫苑が泳ぎを指導してくれ始めた。","korean":"바다에 들어가서도 튜브를 놓지 못하고 엉성한 개헤엄만 치고 있으니,\n보다 못한 시온이 수영을 가르쳐 주기 시작했다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1619,"id":"com_11.ks#1619","kind":"text","speaker":"나레이션","english":"","japanese":"手を引いて、子供に泳ぎを教える時のようなバタ足の訓練だ。","korean":"아이한테 수영을 가르치듯 손을 잡아 주고 발차기를 시킨다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1627,"id":"com_11.ks#1627","kind":"text","speaker":"紫苑","english":"","japanese":"「ほら、しっかり！　正確な型で泳いだ方が、\n身体への負担も少なくて楽に長い距離進めるんだから」","korean":"「자, 똑바로 해! 자세를 제대로 잡아야\n몸에 힘도 덜 들고 더 멀리 갈 수 있거든.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1633,"id":"com_11.ks#1633","kind":"text","speaker":"名前","english":"","japanese":"「う、うん……ええと、まずはバタ足が基本、なんだよね？\nうわっ、わぷっ……！」","korean":"「으, 응…… 일단 발차기부터 하면 되는 거지?\n으악, 푸흡……!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1646,"id":"com_11.ks#1646","kind":"text","speaker":"紫苑","english":"","japanese":"「もう、力の入れすぎなのよ。だから、沈むの。\n力を抜いて、まずは浮いて、それから足を……」","korean":"「아휴, 힘을 너무 줘서 가라앉는 거야.\n힘 빼고 일단 떠 봐. 그다음에 발을……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1652,"id":"com_11.ks#1652","kind":"text","speaker":"名前","english":"","japanese":"「うん、まずはええと、浮かんで……\nはあ、ふう、うぶぶっ、しょっぱいっ……」","korean":"「응, 일단 뜨고……\n하아, 후우, 푸푸흡…… 짜!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1656,"id":"com_11.ks#1656","kind":"text","speaker":"나레이션","english":"","japanese":"紫苑がぼくの手をつかんで、引っ張りながら\n指導してくれるも、どうにも上手くいかない。","korean":"시온이 내 손을 잡아끌며 가르쳐 주는데도 도통 잘되지 않는다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1660,"id":"com_11.ks#1660","kind":"text","speaker":"나레이션","english":"","japanese":"どうも海水が顔にかかったりとか、\n口が海に入って息が出来ないとダメになる感じ……。","korean":"얼굴에 바닷물이 튀거나 입이 잠겨 숨을 못 쉬면 그대로 허둥대게 된다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1665,"id":"com_11.ks#1665","kind":"text","speaker":"名前","english":"","japanese":"「手、手を離さないで……！」","korean":"「소, 손 놓지 마……!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1672,"id":"com_11.ks#1672","kind":"text","speaker":"紫苑","english":"","japanese":"「え？　あっ、手……やだ、手なんか繋いで……！」","korean":"「응? 앗, 손…… 뭐야, 나 손 잡고 있었잖아……!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1677,"id":"com_11.ks#1677","kind":"text","speaker":"名前","english":"","japanese":"「わっ！？　離さないで、おわぁっ……！！」","korean":"「으악?! 놓지 마, 으아아……!!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1689,"id":"com_11.ks#1689","kind":"text","speaker":"紫苑","english":"","japanese":"「あっ、あっ、ご、ごめん……わ、ちょ、ちょっと！！」","korean":"「앗, 아, 미, 미안…… 으앗, 자, 잠깐만!!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1713,"id":"com_11.ks#1713","kind":"text","speaker":"名前","english":"","japanese":"「ぶはあっ……！」","korean":"「푸하아……!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1716,"id":"com_11.ks#1716","kind":"text","speaker":"나레이션","english":"","japanese":"急に手を離されて海中へと沈みかけたところで、\n紫苑が慌てて抱き締めるようにして引き上げてくれた。","korean":"갑자기 손을 놓치는 바람에 물속으로 가라앉을 뻔했는데,\n시온이 황급히 나를 끌어안다시피 해서 끌어올려 줬다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1721,"id":"com_11.ks#1721","kind":"text","speaker":"名前","english":"","japanese":"「ありがとう、紫苑、うぶっ……」","korean":"「고마워, 시온아. 푸흡……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1725,"id":"com_11.ks#1725","kind":"text","speaker":"紫苑","english":"","japanese":"「あ……きゃああっ！！　何っ、胸っ、やっ、やだ、離れてよー！！」","korean":"「앗…… 꺄아아!! 뭐야, 가슴에…… 시, 싫어, 떨어져!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1730,"id":"com_11.ks#1730","kind":"text","speaker":"名前","english":"","japanese":"「うぶはああっ！？」","korean":"「푸하아악?!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1741,"id":"com_11.ks#1741","kind":"text","speaker":"나레이션","english":"","japanese":"助かった、と思ったら、紫苑の胸元に頭が突っ込んでいたようだ。","korean":"살았다고 생각했는데 내 머리가 시온의 가슴팍에 파묻혀 있었나 보다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1744,"id":"com_11.ks#1744","kind":"text","speaker":"나레이션","english":"","japanese":"今のぼくには、柔らかさを感じるような余裕はまったくない。","korean":"지금 나는 그 감촉이 어떤지 느낄 여유 따위 없다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1747,"id":"com_11.ks#1747","kind":"text","speaker":"나레이션","english":"","japanese":"紫苑は慌ててぼくを突き飛ばし、ぼくは再び海中へと沈んでいく。","korean":"시온이 당황해서 나를 밀쳐 내고, 나는 다시 바닷속으로 가라앉는다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1751,"id":"com_11.ks#1751","kind":"text","speaker":"紫苑","english":"","japanese":"「ああもう！　ほら、つかまって！！」","korean":"「아, 정말! 자, 붙잡아!!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1779,"id":"com_11.ks#1779","kind":"text","speaker":"名前","english":"","japanese":"「き、急に手を放さないでもらえると、はあ、はあっ……」","korean":"「가, 갑자기 손 놓지 좀 말아 줘. 하아, 하아……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1787,"id":"com_11.ks#1787","kind":"text","speaker":"紫苑","english":"","japanese":"「い、言われなくてもそうするわよ！\nていうか、子供の頃より泳ぐの下手になってない！？」","korean":"「아, 안 그래도 그럴 거야!\n그보다 너, 어릴 때보다 수영 더 못하는 거 아냐?!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1793,"id":"com_11.ks#1793","kind":"text","speaker":"名前","english":"","japanese":"「すみません……」","korean":"「죄송합니다……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1796,"id":"com_11.ks#1796","kind":"text","speaker":"나레이션","english":"","japanese":"自分でも思った……苦手云々よりも、思ったように身体が動かない感じ。\nこれまでの運動不足のツケが祟ったのかもしれない。","korean":"나도 그렇게 생각했다. 수영이 어렵고 말고를 떠나 몸이 생각대로 움직이질 않는다.\n그동안 운동을 안 한 대가를 치르는 건가.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1800,"id":"com_11.ks#1800","kind":"text","speaker":"나레이션","english":"","japanese":"プールの授業があったのも子供の頃だし、感覚がおっついていないのかも。\n……この夏は、本気で水泳の特訓をすべきな気がしてきた。","korean":"수영장 수업을 들은 것도 어릴 때라 감각을 잊은 건지도 모르겠다.\n……이번 여름엔 정말 수영 연습을 해야 할 것 같다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1818,"id":"com_11.ks#1818","kind":"text","speaker":"水蓮","english":"","japanese":"「ふふ、楽しそうだね、二人とも。こういうの、いいなぁ」","korean":"「후후, 둘 다 재밌어 보이네. 이런 모습 보니까 좋다.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1826,"id":"com_11.ks#1826","kind":"text","speaker":"水蓮","english":"","japanese":"「帰ってきてくれて、本当によかった……\nありがとう、くすっ……」","korean":"「돌아와 줘서 정말 다행이야……\n고마워. 후훗……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1833,"id":"com_11.ks#1833","kind":"text","speaker":"나레이션","english":"","japanese":"浜辺では、水蓮姉さんが何だか満足そうに微笑んでいた。","korean":"모래사장에서는 스이렌 누나가 왠지 흐뭇한 미소를 짓고 있었다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1844,"id":"com_11.ks#1844","kind":"text","speaker":"名前","english":"","japanese":"「うう、はあ、はあ、うぶぶっ、ぶはっ……」","korean":"「으으, 하아, 하아, 푸푸흡, 푸하……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1848,"id":"com_11.ks#1848","kind":"text","speaker":"나레이션","english":"","japanese":"その優しいまなざしに見守られつつ、\nぼくは、溺れたり沈んだりと忙しくしていた。","korean":"누나가 저렇게 다정한 눈으로 지켜봐 주는 동안,\n나는 물에 빠졌다 가라앉았다 하느라 바빴다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1866,"id":"com_11.ks#1866","kind":"text","speaker":"紫苑","english":"","japanese":"「それじゃ、私、向こうで撮影してくるから」","korean":"「그럼 난 저쪽에서 사진 좀 찍고 올게.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1872,"id":"com_11.ks#1872","kind":"text","speaker":"나레이션","english":"","japanese":"それからしばらくの後、ぼくがすっかり疲れてぐったりしたのを\n見計らうかのようにして、紫苑は海から上がって岩場の向こうへ歩いていった。","korean":"그렇게 한참 지나 내가 완전히 지쳐 축 늘어지자, 그때를 기다렸던 것처럼\n시온은 물에서 나와 바위 너머로 걸어갔다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1876,"id":"com_11.ks#1876","kind":"text","speaker":"나레이션","english":"","japanese":"ぼくも全身にほどよい疲労感を感じつつ、浜に上がってきた。","korean":"나도 온몸에 기분 좋은 피로를 느끼며 모래사장으로 돌아왔다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1881,"id":"com_11.ks#1881","kind":"text","speaker":"名前","english":"","japanese":"「あれってデジタルの一眼レフだよね」","korean":"「저거 DSLR이지?」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1884,"id":"com_11.ks#1884","kind":"text","speaker":"나레이션","english":"","japanese":"歩き去っていく紫苑の手にはカメラが大切そうに抱えられていた。","korean":"걸어가는 시온이 카메라를 소중하게 끌어안고 있다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1887,"id":"com_11.ks#1887","kind":"text","speaker":"나레이션","english":"","japanese":"この前見た時は寝ぼけてたし、あんまりまじまじと見なかったけど、\nかなり本格的なカメラに見えた。","korean":"저번엔 잠이 덜 깨서 제대로 보지 못했는데, 꽤 본격적인 카메라 같았다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1895,"id":"com_11.ks#1895","kind":"text","speaker":"水蓮","english":"","japanese":"「そうだよ。紫苑はカメラが趣味なの」","korean":"「맞아. 시온이는 사진 찍는 게 취미야.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1900,"id":"com_11.ks#1900","kind":"text","speaker":"名前","english":"","japanese":"「へぇ、そうなんだ……」","korean":"「아, 그렇구나……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1907,"id":"com_11.ks#1907","kind":"text","speaker":"水蓮","english":"","japanese":"「詳しいね。デジタル一眼レフ、ってすぐわかったんだ」","korean":"「잘 아네. 보자마자 DSLR인 줄도 알고.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1914,"id":"com_11.ks#1914","kind":"text","speaker":"名前","english":"","japanese":"「ぼく自身は持ってないんだけど、最近、持ってる人多いからなんとなくね」","korean":"「난 없는데 요즘 갖고 다니는 사람이 많아서 얼핏 알아.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1918,"id":"com_11.ks#1918","kind":"text","speaker":"나레이션","english":"","japanese":"前に展望台にいたのも、もしかしたら撮影してたのかもなぁ。","korean":"저번에 전망대에 있던 것도 사진 찍으러 갔다가 그랬으려나.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1926,"id":"com_11.ks#1926","kind":"text","speaker":"水蓮","english":"","japanese":"「はいどうぞ。ジュースでいいよね？」","korean":"「자, 여기. 주스면 되지?」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1931,"id":"com_11.ks#1931","kind":"text","speaker":"名前","english":"","japanese":"「ありがとう、水蓮姉さん」","korean":"「고마워, 스이렌 누나.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1941,"id":"com_11.ks#1941","kind":"text","speaker":"나레이션","english":"","japanese":"ぼくは、水蓮姉さんが準備してくれた飲み物をもらって、\n二人並んで浜に腰を下ろし、休憩することにした。","korean":"스이렌 누나가 챙겨 준 주스를 받아 들고,\n둘이 나란히 모래사장에 앉아 쉬기로 했다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1946,"id":"com_11.ks#1946","kind":"text","speaker":"名前","english":"","japanese":"「さすがに、疲れたよ……こんなに泳いだの、子供の頃以来だ」","korean":"「아, 지친다…… 이렇게 많이 헤엄친 건 어릴 때 이후로 처음이야.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1953,"id":"com_11.ks#1953","kind":"text","speaker":"水蓮","english":"","japanese":"「うん。久しぶりだよね、みんなでこうして泳ぐのも」","korean":"「응. 다 같이 이렇게 수영하는 것도 오랜만이지.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1958,"id":"com_11.ks#1958","kind":"text","speaker":"名前","english":"","japanese":"「……うん、そうだね。かなり久しぶりだなぁ……」","korean":"「……응, 그러네. 정말 오랜만이다……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1961,"id":"com_11.ks#1961","kind":"text","speaker":"나레이션","english":"","japanese":"くっつかれ、ふんわりと微笑まれ、さらにじーっと見つめられてしまい、\nこそばゆいというか、照れくさくてもぞもぞしてしまう。","korean":"스이렌 누나가 바짝 붙어 다정하게 웃더니 내 얼굴을 빤히 들여다본다.\n쑥스러워서 괜히 몸을 꼼지락거린다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1970,"id":"com_11.ks#1970","kind":"text","speaker":"水蓮","english":"","japanese":"「ふふ、じっと見ると、恥ずかしいんだよね？\n子供の頃から、そうだったなぁ……」","korean":"「후후, 이렇게 빤히 보면 쑥스럽지?\n어릴 때부터 그랬잖아……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1976,"id":"com_11.ks#1976","kind":"text","speaker":"名前","english":"","japanese":"「え？」","korean":"「어?」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1984,"id":"com_11.ks#1984","kind":"text","speaker":"水蓮","english":"","japanese":"「なんでもない。くすっ、\n久しぶりだし、もっとまじまじ見合っちゃおうか？」","korean":"「아무것도 아니야. 후훗.\n오랜만인데 우리 서로 얼굴 좀 더 자세히 볼까?」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1990,"id":"com_11.ks#1990","kind":"text","speaker":"名前","english":"","japanese":"「ほ、ほどほどにしてね……ちょっと照れくさいからさ」","korean":"「저, 적당히 봐 줘…… 좀 쑥스러워서.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1993,"id":"com_11.ks#1993","kind":"text","speaker":"나레이션","english":"","japanese":"間近でまっすぐに見つめられていると、本当にどうしていいかわからず\n耳たぶまで熱くなってドキドキしてくる。","korean":"코앞에서 똑바로 바라보니 어쩔 줄을 모르겠다.\n귓불까지 뜨거워지고 심장이 쿵쾅거린다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":1997,"id":"com_11.ks#1997","kind":"text","speaker":"나레이션","english":"","japanese":"こういう時、もっと口が上手ければ気の利いたことを言えるんだろうけど、\n今のぼくには無理だと思われる……。","korean":"이럴 때 말을 잘하는 사람이면 뭐라도 센스 있게 받아쳤겠지만,\n지금 내겐 그럴 여유가 없다……","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2005,"id":"com_11.ks#2005","kind":"text","speaker":"水蓮","english":"","japanese":"「……三人でまたこうして過ごせて……お姉ちゃん、とっても幸せ」","korean":"「……우리 셋이 다시 이렇게 지낼 수 있어서…… 누나는 정말 행복해.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2009,"id":"com_11.ks#2009","kind":"text","speaker":"名前","english":"","japanese":"「……っ……」","korean":"「……읏……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2013,"id":"com_11.ks#2013","kind":"text","speaker":"나레이션","english":"","japanese":"水蓮姉さんは、大輪の花がパァッと咲くように笑って、\nぐっと顔を近づけてきた。","korean":"스이렌 누나가 커다란 꽃이 피듯 활짝 웃더니, 얼굴을 가까이 가져왔다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2017,"id":"com_11.ks#2017","kind":"text","speaker":"나레이션","english":"","japanese":"鼓動がさらに速くなり、呼吸まで苦しくなってきたように感じる。\nだって、これ、ぼくが顔を突き出したら、キスできちゃうような距離で──","korean":"심장이 더 빨리 뛰고 숨까지 가빠지는 것 같다.\n이 거리면 내가 고개만 조금 내밀어도 입이 닿을 텐데……","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2022,"id":"com_11.ks#2022","kind":"text","speaker":"名前","english":"","japanese":"「ぼ、ぼくもすごく嬉しいよ……こういう時間を、また過ごせて……」","korean":"「나, 나도 정말 좋아…… 이렇게 다시 같이 있을 수 있어서……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2026,"id":"com_11.ks#2026","kind":"text","speaker":"나레이션","english":"","japanese":"水蓮姉さんの近さが不味い……！　息遣いを感じられる距離は不味い……！！","korean":"너무 가깝다, 스이렌 누나……! 숨결까지 닿는 거리는 위험하다고……!!","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2030,"id":"com_11.ks#2030","kind":"text","speaker":"名前","english":"","japanese":"「あ、あの、ちょっと、その辺歩いて来るね、久しぶりだし！」","korean":"「아, 저기, 나 잠깐 주위 좀 걷고 올게. 여기 온 것도 오랜만이고!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2033,"id":"com_11.ks#2033","kind":"text","speaker":"나레이션","english":"","japanese":"一刻も早くこの場を離れないと、また勃起しかねない。\nむしろ、ちょっとむくってしかけてるから、このままは危険だ。","korean":"한시라도 빨리 여기서 벗어나야 한다. 안 그럼 또 아래가 설지도 모른다.\n이미 조금 반응하기 시작했으니 이대로 있다간 큰일이다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2043,"id":"com_11.ks#2043","kind":"text","speaker":"水蓮","english":"","japanese":"「うん、わかった。気をつけてね。\n……紫苑がいても、そっとしておいてあげてね。撮影中だと思うから」","korean":"「응, 알았어. 조심해서 다녀와.\n……시온이 보이더라도 그냥 둬. 아마 사진 찍고 있을 거야.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2049,"id":"com_11.ks#2049","kind":"text","speaker":"名前","english":"","japanese":"「わかった、声はかけずに、静かに通り過ぎるようにするよ」","korean":"「알았어. 말 걸지 말고 조용히 지나갈게.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2057,"id":"com_11.ks#2057","kind":"text","speaker":"나레이션","english":"","japanese":"ぼくは立ち上がり、水蓮姉さんに軽く手を振って、\n周囲を散策してみることにした。","korean":"자리에서 일어나 스이렌 누나에게 가볍게 손을 흔들고, 근처를 둘러보기로 했다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2061,"id":"com_11.ks#2061","kind":"text","speaker":"나레이션","english":"","japanese":"水蓮姉さんには申し訳ないが、あのまま居たら勃起して……絶対バレたと思う。\n少しクールダウンしないと。","korean":"누나한테는 미안하지만 그대로 있었으면 아래가 서서 들켰을 게 뻔하다.\n좀 진정부터 해야겠다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2075,"id":"com_11.ks#2075","kind":"text","speaker":"나레이션","english":"","japanese":"そして、ぶらぶらと浜を歩き、ぼくは岩礁のあたりにたどり着いた。","korean":"그렇게 해변을 느긋하게 걷다 바위가 드러난 곳까지 왔다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2079,"id":"com_11.ks#2079","kind":"text","speaker":"名前","english":"","japanese":"「あっ……」","korean":"「아……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2091,"id":"com_11.ks#2091","kind":"text","speaker":"나레이션","english":"","japanese":"膝をついてカメラを覗き込み、何か撮影している紫苑を見つけた。","korean":"한쪽 무릎을 꿇고 카메라를 들여다보며 뭔가 찍는 시온이 보였다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2094,"id":"com_11.ks#2094","kind":"text","speaker":"나레이션","english":"","japanese":"場所的には、多分波のきらめきとか、空と海の間に立つ\n岩礁とかを被写体にしてるんだと思うけど……","korean":"여기라면 반짝이는 물결이나 하늘과 바다 사이에 솟은 바위를 찍는 거겠지만……","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2099,"id":"com_11.ks#2099","kind":"text","speaker":"名前","english":"","japanese":"「……」","korean":"「……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2102,"id":"com_11.ks#2102","kind":"text","speaker":"나레이션","english":"","japanese":"ぼくは水蓮姉さんとの約束を思い出し、そっと口を閉じた。","korean":"스이렌 누나한테 한 약속이 생각나 조용히 입을 다물었다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2107,"id":"com_11.ks#2107","kind":"text","speaker":"紫苑","english":"","japanese":"「ふふっ……」","korean":"「후후……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2111,"id":"com_11.ks#2111","kind":"text","speaker":"名前","english":"","japanese":"（……あ……）","korean":"(……아……)","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2114,"id":"com_11.ks#2114","kind":"text","speaker":"나레이션","english":"","japanese":"その時、ファインダーを覗く紫苑が、ごく自然な感じで楽しげに笑った。","korean":"그때 카메라를 들여다보던 시온이 꾸밈없이 즐거운 얼굴로 웃었다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2117,"id":"com_11.ks#2117","kind":"text","speaker":"나레이션","english":"","japanese":"きっと、いい被写体を見つけたんだろう。\n本当に自然な、素直な笑顔のように感じた。","korean":"마음에 드는 걸 찾았나 보다.\n본심이 고스란히 드러나는, 참 자연스러운 미소였다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2121,"id":"com_11.ks#2121","kind":"text","speaker":"나레이션","english":"","japanese":"……正直、この島に来てから彼女の笑顔を見たことがほとんどないのもあって、\n穏やかな紫苑の笑顔の可愛さに、思わず胸が高鳴った。","korean":"……섬에 온 뒤로 시온이 웃는 걸 거의 못 봐서 그런지,\n저렇게 편안하게 웃는 시온이 너무 귀여워 가슴이 두근거렸다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2126,"id":"com_11.ks#2126","kind":"text","speaker":"名前","english":"","japanese":"（そっか、こういうことか……だから、水蓮姉さんは\n邪魔しないように、って言ったんだな）","korean":"(아, 이런 거였구나…… 그래서 스이렌 누나가 방해하지 말라고 한 거구나.)","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2130,"id":"com_11.ks#2130","kind":"text","speaker":"나레이션","english":"","japanese":"紫苑が一番素直になれる時間……それが撮影している時なんだろう。","korean":"시온이 가장 솔직해지는 건 사진을 찍을 때인 모양이다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2133,"id":"com_11.ks#2133","kind":"text","speaker":"나레이션","english":"","japanese":"とりあえず、そーっと戻ることにしよう。","korean":"일단은 조용히 돌아가자.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2136,"id":"com_11.ks#2136","kind":"text","speaker":"나레이션","english":"","japanese":"……もう少しあの笑顔を見ていたい気持ちもあるけど、邪魔しちゃ悪い。","korean":"……저 미소를 조금 더 보고 싶긴 한데, 방해하면 안 되니까.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2154,"id":"com_11.ks#2154","kind":"text","speaker":"名前","english":"","japanese":"「ふう……」","korean":"「후우……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2157,"id":"com_11.ks#2157","kind":"text","speaker":"나레이션","english":"","japanese":"美しい景色と、紫苑の意外な様子に心なごんだからか、\nなんとなく落ち着いてきた。","korean":"아름다운 풍경과 시온의 뜻밖의 모습에 마음이 편해져서인지, 어느새 조금 진정됐다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2161,"id":"com_11.ks#2161","kind":"text","speaker":"나레이션","english":"","japanese":"軽く深呼吸しながら、水蓮姉さんのいるあたりに戻ることにした。","korean":"가볍게 심호흡을 하고 스이렌 누나가 있는 곳으로 돌아갔다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2180,"id":"com_11.ks#2180","kind":"text","speaker":"水蓮","english":"","japanese":"「大漁大漁、かな、うふふ」","korean":"「오늘은 많이도 건졌네. 후후.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2184,"id":"com_11.ks#2184","kind":"text","speaker":"名前","english":"","japanese":"「えっ……」","korean":"「어……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2187,"id":"com_11.ks#2187","kind":"text","speaker":"나레이션","english":"","japanese":"戻ってみると、水蓮姉さんは満面の笑みで佇んでいた。","korean":"돌아와 보니 스이렌 누나가 함박웃음을 지으며 서 있었다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2190,"id":"com_11.ks#2190","kind":"text","speaker":"나레이션","english":"","japanese":"どうやら、素潜りで貝を採っていたらしい。\n彼女の足元には、結構たくさんの収穫物が積まれている。","korean":"누나가 숨을 참고 잠수해서 조개를 캔 모양이다.\n발밑에는 건져 올린 조개가 제법 많이 쌓여 있다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2200,"id":"com_11.ks#2200","kind":"text","speaker":"水蓮","english":"","japanese":"「、おかえりなさい。ほら、見て、割とたくさん採れたよ」","korean":"「어서 와. 여기 봐, 제법 많이 캤어.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2208,"id":"com_11.ks#2208","kind":"text","speaker":"名前","english":"","japanese":"「すごいね、こんなに……自分たちで食べる分とおすそ分け用だっけ……」","korean":"「와, 이렇게나 많이…… 둘이 먹을 거랑 손님들한테 나눠 줄 거였지?」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2216,"id":"com_11.ks#2216","kind":"text","speaker":"水蓮","english":"","japanese":"「うん。漁協の許可ももらって、週に何回か採ってるの。\n貝とかウニとか、魚介類をね」","korean":"「응. 어업조합 허락은 받았고, 일주일에 몇 번씩 채취해.\n조개나 성게 같은 해산물 말이야.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2222,"id":"com_11.ks#2222","kind":"text","speaker":"名前","english":"","japanese":"「そうなんだ……海産物好きからしたら、垂涎の環境だね」","korean":"「그렇구나…… 해산물 좋아하는 사람한텐 천국이겠네.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2231,"id":"com_11.ks#2231","kind":"text","speaker":"水蓮","english":"","japanese":"「やってみる？\nそうだ、ついでに紫苑が戻ってくるまで、私が泳ぎの特訓してあげようか？」","korean":"「너도 해 볼래?\n아, 그러면 시온이 돌아올 때까지 내가 수영도 가르쳐 줄까?」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2240,"id":"com_11.ks#2240","kind":"text","speaker":"名前","english":"","japanese":"「えっと……うん、よろしくお願いします」","korean":"「어…… 응, 잘 부탁해.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2244,"id":"com_11.ks#2244","kind":"text","speaker":"나레이션","english":"","japanese":"泳ぎの特訓、と聞いてちょっと躊躇したけど、せっかくこの島に来たんだから、\nどうせならもう少しは、泳げるようにはなっておきたい……かもしれない。","korean":"수영 연습이라는 말에 잠깐 망설였지만, 모처럼 여기까지 왔으니,\n기왕이면 지금보다는 좀 더 잘하게 되고 싶다…… 아마도.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2276,"id":"com_11.ks#2276","kind":"text","speaker":"水蓮","english":"","japanese":"「はい、そのまま、バタバタして……\n力まずに、最初はゆっくりでいいからね」","korean":"「자, 그대로 발을 차 봐……\n힘은 빼고. 처음엔 천천히 해도 괜찮아.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2282,"id":"com_11.ks#2282","kind":"text","speaker":"名前","english":"","japanese":"「了解、えいっ、ぶはっ……」","korean":"「알았어. 자, 푸하……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2288,"id":"com_11.ks#2288","kind":"text","speaker":"水蓮","english":"","japanese":"「ふふ、こっちこっち……」","korean":"「후후, 이리 와. 여기야……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2293,"id":"com_11.ks#2293","kind":"text","speaker":"名前","english":"","japanese":"「うん……っ、ぶふっ！？」","korean":"「응…… 읏, 푸흡?!」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2317,"id":"com_11.ks#2317","kind":"text","speaker":"水蓮","english":"","japanese":"「うふふ」","korean":"「후후후.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2320,"id":"com_11.ks#2320","kind":"text","speaker":"나레이션","english":"","japanese":"ぼくを引っ張ってくれているはずなのに、なぜか急に止まって、\nわざとのようにおっぱいで出迎えてくれる水蓮姉さん。","korean":"나를 잡아끌어 주는 줄 알았는데 스이렌 누나가 갑자기 멈춘다.\n일부러 그러는 것처럼 내 얼굴이 누나 가슴팍에 부딪친다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2325,"id":"com_11.ks#2325","kind":"text","speaker":"名前","english":"","japanese":"「はあ、うう、はあっ、はぁっ……」","korean":"「하아, 으으, 하아, 하아……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2328,"id":"com_11.ks#2328","kind":"text","speaker":"나레이션","english":"","japanese":"おかげで、溺れそうになったりおっぱい当たって、\nムギュッと圧迫されたりと、息つく暇もない。","korean":"덕분에 물에 빠질 뻔하다가 가슴에 부딪치고, 또 꽉 눌리고,\n숨 돌릴 틈도 없다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2332,"id":"com_11.ks#2332","kind":"text","speaker":"나레이션","english":"","japanese":"こんなモノ、目の前にあるだけでもたまらないのに、\n押しつけられたり飛び込まされたりした日には……。","korean":"눈앞에 있는 것만 봐도 정신이 없는데, 이렇게 얼굴이 눌리거나 파묻히기까지 하면……","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2337,"id":"com_11.ks#2337","kind":"text","speaker":"名前","english":"","japanese":"「ふう、はあ、うう、うぐぐっ……」","korean":"「후우, 하아, 으으, 으으윽……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2341,"id":"com_11.ks#2341","kind":"text","speaker":"나레이션","english":"","japanese":"ぼくは、悶々としながら、ひたすら無心でバタ足を繰り返すしかなかった。","korean":"나는 온갖 생각을 참아 가며 머리를 비우고 발차기만 계속할 수밖에 없었다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2355,"id":"com_11.ks#2355","kind":"text","speaker":"水蓮","english":"","japanese":"「ほら、頑張れ、頑張れ！\n大丈夫、お姉ちゃんがついてるから、安心してね」","korean":"「자, 힘내. 파이팅!\n괜찮아, 누나가 잡아 주고 있으니까 걱정 마.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2361,"id":"com_11.ks#2361","kind":"text","speaker":"名前","english":"","japanese":"「う、うっ……」","korean":"「으, 윽……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2364,"id":"com_11.ks#2364","kind":"text","speaker":"나레이션","english":"","japanese":"水蓮姉さんと密着しているからこそ、安心できない。\n心穏やかに泳ぎの練習に集中できないのに、気付いて欲しかった。","korean":"스이렌 누나랑 이렇게 딱 붙어 있으니까 마음이 안 놓이는 건데.\n이래서는 수영에 집중할 수 없다는 걸 좀 알아줬으면 좋겠다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2388,"id":"com_11.ks#2388","kind":"text","speaker":"나레이션","english":"","japanese":"そうやって、新手の精神鍛錬に精を出すうちに、\nだんだん日も翳ってきたように感じられた。","korean":"그렇게 별난 정신 수련에 매달리다 보니, 어느새 햇빛도 조금씩 약해지는 것 같았다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2395,"id":"com_11.ks#2395","kind":"text","speaker":"紫苑","english":"","japanese":"「、お姉ちゃん」","korean":"「언니.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2398,"id":"com_11.ks#2398","kind":"text","speaker":"나레이션","english":"","japanese":"ちょうど紫苑も戻ってきたので、\nぼくたちは夕方になる前に引き上げることとなった。","korean":"마침 시온도 돌아와서 우리는 저녁이 되기 전에 해변을 떠나기로 했다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2419,"id":"com_11.ks#2419","kind":"text","speaker":"水蓮","english":"","japanese":"「それじゃ、帰りましょ」","korean":"「그럼 이제 돌아가자.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2424,"id":"com_11.ks#2424","kind":"text","speaker":"紫苑","english":"","japanese":"「うん」","korean":"「응.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2428,"id":"com_11.ks#2428","kind":"text","speaker":"名前","english":"","japanese":"「家までこのまま水着で帰って、シャワー浴びて着替える……って感じかな」","korean":"「집까진 이대로 수영복 입고 가서 씻은 뒤 갈아입으면 되겠네.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2435,"id":"com_11.ks#2435","kind":"text","speaker":"水蓮","english":"","japanese":"「そうよ。子供の頃はいつもそうだったでしょ、ふふ」","korean":"「맞아. 어릴 때도 항상 그랬잖아. 후후.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2444,"id":"com_11.ks#2444","kind":"text","speaker":"水蓮","english":"","japanese":"「、あの頃はうちから海水パンツでここまで来て、\nそのまま帰ってたよね、くすっ……」","korean":"「너 그땐 집에서부터 수영복 바람으로 여기까지 왔다가,\n그대로 다시 돌아가곤 했지. 후훗.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2449,"id":"com_11.ks#2449","kind":"text","speaker":"名前","english":"","japanese":"「ああ、そういえばそうだったっけ……」","korean":"「아, 그러고 보니 그랬다……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2457,"id":"com_11.ks#2457","kind":"text","speaker":"紫苑","english":"","japanese":"「、空いてるコテージのシャワー使ったら？\n私とお姉ちゃんは、家の……」","korean":"「빈 숙소에 있는 샤워실 쓰면 어때?\n나랑 언니는 집에서……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2465,"id":"com_11.ks#2465","kind":"text","speaker":"水蓮","english":"","japanese":"「みんなで一緒にシャワー浴びましょ？\nいいでしょ、水着のまんまで浴びるんだから」","korean":"「우리 셋이 같이 씻자.\n수영복 입은 채로 씻는 건 괜찮잖아?」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2471,"id":"com_11.ks#2471","kind":"text","speaker":"名前","english":"","japanese":"「うっ……」","korean":"「읏……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2477,"id":"com_11.ks#2477","kind":"text","speaker":"紫苑","english":"","japanese":"「シャワーは良くてもその後、着替えるでしょ？\nダメダメ、男女は別だからね」","korean":"「씻는 건 괜찮아도 그다음엔 옷 갈아입어야 하잖아.\n안 돼. 남녀는 따로야.」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2483,"id":"com_11.ks#2483","kind":"text","speaker":"名前","english":"","japanese":"「ははは……」","korean":"「하하하……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2486,"id":"com_11.ks#2486","kind":"text","speaker":"나레이션","english":"","japanese":"これは、帰ってからも大変そうだ。\n無事にシャワーを浴びられるかどうか。","korean":"집에 돌아가서도 만만찮겠는데.\n과연 무사히 샤워나 할 수 있을까.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2507,"id":"com_11.ks#2507","kind":"text","speaker":"水蓮","english":"","japanese":"「着替えたら、早めに晩ご飯にしようか。\n泳いでお腹空いたでしょ、二人とも」","korean":"「옷 갈아입으면 저녁 일찍 먹을까?\n둘 다 헤엄쳐서 배고프지?」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2513,"id":"com_11.ks#2513","kind":"text","speaker":"紫苑","english":"","japanese":"「その方がいいかも。\n水泳って全身運動だから、すっごくお腹減るもんね……」","korean":"「그게 좋겠다.\n수영은 몸을 전부 쓰니까 진짜 배고프거든……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2518,"id":"com_11.ks#2518","kind":"text","speaker":"名前","english":"","japanese":"「…………」","korean":"「…………」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2521,"id":"com_11.ks#2521","kind":"text","speaker":"나레이션","english":"","japanese":"帰り道、海パンのまま荷物を担いで道を歩きながら、\nぼくはうつむき太ももをもじもじさせている。","korean":"돌아가는 길, 수영복 차림으로 짐을 둘러멘 나는\n고개를 푹 숙인 채 자꾸 다리를 꼼지락거린다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2525,"id":"com_11.ks#2525","kind":"text","speaker":"나레이션","english":"","japanese":"目の前を歩く、水蓮姉さんと紫苑。\nつまり、目の前で二人のぷりぷりと形のいいお尻が揺れているのだ。","korean":"앞에는 스이렌 누나와 시온이 걸어간다.\n그러니까 바로 눈앞에서 두 사람의 탄탄한 엉덩이가 흔들리고 있다는 얘기다.","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2529,"id":"com_11.ks#2529","kind":"text","speaker":"나레이션","english":"","japanese":"でも、我慢、我慢だ。\nとにかく、見ないようにして、平常心、無心、修行僧の境地で──","korean":"그래도 참아야 한다. 참자.\n보지 말고 평정심을 되찾자. 아무 생각 없이, 수행승처럼……","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2540,"id":"com_11.ks#2540","kind":"text","speaker":"水蓮","english":"","japanese":"「うふふ、そうそう、だったら……」","korean":"「후후, 맞아. 그럼……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2545,"id":"com_11.ks#2545","kind":"text","speaker":"紫苑","english":"","japanese":"「だよね、あはは……じゃあ、今度は……」","korean":"「그치? 하하…… 그럼 다음엔……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2549,"id":"com_11.ks#2549","kind":"text","speaker":"名前","english":"","japanese":"「……う、ぐ……」","korean":"「……으, 윽……」","recordingScript":"","memo":"","voice":"","phaseId":""},
{"rowNumber":2552,"id":"com_11.ks#2552","kind":"text","speaker":"나레이션","english":"","japanese":"でもどうしても、目に入ってしまう。\nぷりっと引き締まった二つのお尻が、すぐそばで揺れているんだから。無理だ。","korean":"그런데 아무리 해도 눈에 들어온다.\n탄탄한 엉덩이 두 개가 바로 앞에서 흔들리고 있는데, 안 보는 건 무리다.","recordingScript":"","memo":"","voice":"","phaseId":""}
];
